  --jet:#000000;
  --paper:#F4F1E8;
  --ink:#151515;
  --graphite:#5B5B5B;
  --hairline:#D8D6CC;
  --signal:#3b66d6;
  --deep:#3b66d6;
  --pale:#E8EDFF;

  --font:-apple-system,BlinkMacSystemFont,"Inter","Segoe UI",Roboto,Helvetica,Arial,sans-serif;

  /* ---- canonical type scale (theme v2.1 typography.scale) ----
     Fluid between the lock's mobile column (<=620px) and its desktop column (>=1440px).
     Every size on this page comes from this ladder. No off-scale values. */
  --t-display:clamp(40px, calc(40px + 36 * (100vw - 620px) / 820), 76px);
  --t-h1:clamp(34px, calc(34px + 22 * (100vw - 620px) / 820), 56px);
  --t-h2:clamp(28px, calc(28px + 12 * (100vw - 620px) / 820), 40px);
  --t-h3:clamp(21px, calc(21px + 5 * (100vw - 620px) / 820), 26px);
  --t-lead:clamp(18px, calc(18px + 3 * (100vw - 620px) / 820), 21px);
  --t-body:clamp(16px, calc(16px + 1 * (100vw - 620px) / 820), 17px);
  --t-small:15px;
  --t-label:12px;

  --lh-display:1.04; --lh-h2:1.15; --lh-h3:1.25; --lh-lead:1.5; --lh-body:1.6;
  --content:1440px;         /* theme space.maxContentWidth */
  --measure:880px;          /* centred content column */
  --pad-x:clamp(20px,4vw,64px);

  --fg:var(--paper);
  --fg-2:rgba(244,241,232,.72);   /* secondary on dark, never Graphite */
  --fg-3:rgba(244,241,232,.55);
  --line-dim:rgba(216,214,204,.18);
}

*{margin:0;padding:0;box-sizing:border-box}
html{-webkit-text-size-adjust:100%;overflow-x:hidden}

a{color:inherit;text-decoration:none}
button,input,textarea,select,code,pre,kbd,samp{font-family:var(--font)}
:focus-visible{outline:2px solid var(--signal);outline-offset:2px}

/* one continuous background field for the whole page, no per-section canvases,
   so there is no seam where two compositions meet */
#v-home #pagebg{position:absolute;top:0;left:0;width:100%;z-index:0;display:block;pointer-events:none}
.wrap{max-width:var(--measure);margin:0 auto}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}

/* ---------- shared button language, radius 2px, never pills ---------- */
#v-home .btn{
  display:inline-block;font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  padding:14px 28px;border-radius:2px;border:1px solid transparent;cursor:pointer}
#v-home .btn-solid{background:var(--ink);color:var(--paper);font-weight:700}
#v-home .btn-ghost{border-color:rgba(21,21,21,.18);color:var(--ink);background:none}

/* ============================ HEADER ============================ */
#v-home .site-head{position:relative;z-index:2;height:66px;flex:0 0 auto}
#v-home .site-head .mark{position:absolute;left:var(--pad-x);top:50%;transform:translateY(-50%);line-height:0}
#v-home .site-head .mark svg{display:block;margin:0}
#v-home .site-head nav{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  display:flex;gap:30px;font-size:var(--t-small);white-space:nowrap
}
#v-home .site-head .actions{
  position:absolute;right:var(--pad-x);top:50%;transform:translateY(-50%);
  display:flex;gap:8px;align-items:center
}
#v-home .site-head .actions .talk{color:rgba(21,21,21,.8);font-size:var(--t-small)}
#v-home .site-head .actions .login{
  background:var(--ink);color:var(--paper);font-size:var(--t-label);font-weight:700;
  letter-spacing:.08em;text-transform:uppercase;padding:9px 16px;border-radius:2px
}
@media(max-width:700px){ #v-home .site-head nav{display:none} }

/* ============================= HERO ============================= */
#v-home #stage{position:relative;overflow:hidden;min-height:100vh;display:flex;flex-direction:column}
#v-home #burst{position:absolute;inset:0;width:100%;height:100%;display:block;z-index:1;pointer-events:none}
#v-home .hero{position:relative;z-index:2;text-align:center;max-width:calc(var(--content) + var(--pad-x)*2);
  margin-inline:auto;padding:clamp(34px,5vw,52px) var(--pad-x);
  flex:1 1 auto;display:flex;flex-direction:column;justify-content:center}
#v-home .hero h1{
  font-size:var(--t-display);line-height:var(--lh-display);letter-spacing:-.02em;font-weight:400;
  margin:0 auto 22px;text-wrap:balance
}
#v-home .hero h1 em{font-style:normal;color:var(--signal)}
#v-home .hero .thesis{
  font-size:var(--t-lead);line-height:var(--lh-lead);color:rgba(21,21,21,.88);
  max-width:62ch;margin:0 auto 36px
}
#v-home .hero .ctas{display:flex;gap:10px;justify-content:center;margin-bottom:46px;flex-wrap:wrap}

/* ---------- interaction card ---------- */
#v-home .card{
  width:min(92%,620px);margin:0 auto;background:var(--paper);
  border:1px solid rgba(21,21,21,.18);border-radius:6px;padding:20px 22px;text-align:left
}
#v-home .card .line{font-size:var(--t-body);line-height:var(--lh-body);margin-bottom:16px;min-height:3.2em}
#v-home .card .row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
#v-home .chip{
  font-size:var(--t-label);padding:9px 14px;border-radius:2px;
  border:1px solid rgba(21,21,21,.32);background:none;color:var(--ink);cursor:pointer
}
#v-home .chip[aria-pressed="true"]{background:var(--ink);color:var(--paper);border-color:var(--ink);font-weight:700}
#v-home .card .spacer{flex:1;min-width:6px}
#v-home .card .agent{
  font-size:var(--t-label);color:var(--graphite);border:1px solid rgba(21,21,21,.22);
  border-radius:2px;padding:9px 12px;white-space:nowrap
}
#v-home .card .agent i{color:rgba(21,21,21,.5);font-size:9px;font-style:normal}
#v-home .card .play{
  width:34px;height:34px;border-radius:50%;border:1px solid rgba(21,21,21,.18);
  background:none;color:var(--ink);font-size:var(--t-label);cursor:pointer;line-height:1;flex:0 0 auto
}

/* ===================== FOOTER ===================== */
#v-home #foot{position:relative;z-index:2;background:var(--paper)}
#v-home #foot .ft-wrap{
  max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;
