  font-weight:400;max-width:22ch
}
#v-home #works .panels{position:relative;z-index:2;max-width:calc(var(--content) + var(--pad-x)*2);
  margin-inline:auto;padding:0 var(--pad-x) clamp(48px,6vw,80px)}

#v-home .grid{position:relative;display:grid;grid-template-columns:repeat(12,1fr);gap:6px}
#v-home .bx{
  position:relative;background:rgba(255,255,255,.58);
  border:1px solid rgba(21,21,21,.12);border-top-color:rgba(21,21,21,.28);
  border-radius:7px;padding:0 22px 24px;overflow:hidden;
  box-shadow:0 14px 34px rgba(16,20,24,0.12),inset 0 1px 0 rgba(255,255,255,.10);
  transition:background .5s,border-color .5s,transform .5s,box-shadow .5s
}
#v-home .bx.on{
  background:rgba(255,255,255,.72);border-color:var(--signal);border-top-color:var(--signal);
  transform:translateY(-3px);
