}
#v-home #b0{grid-column:1/6;grid-row:1}
#v-home #b1{grid-column:6/13;grid-row:1}
#v-home #b3{grid-column:1/8;grid-row:2}
#v-home #b2{grid-column:8/13;grid-row:2}
#v-home canvas.vz{width:calc(100% + 44px);margin-left:-22px;display:block}   /* height is set per panel inline */
#v-home .bx h3{font-size:var(--t-h3);line-height:var(--lh-h3);font-weight:400;margin:20px 0 7px;letter-spacing:-.01em}
#v-home .bx p{font-size:var(--t-small);line-height:1.5;color:rgba(21,21,21,.58)}

@media(max-width:700px){
