/* the silos: four channels that never meet, and the person in the middle of them */
#v-rr .silos{position:relative;margin:clamp(34px,5vw,64px) auto 0;width:100%;max-width:1080px;
  aspect-ratio:1080/470;height:auto}
#v-rr .silo{position:absolute;width:clamp(168px,17vw,224px);padding:14px 16px;text-align:left;
  background:var(--paper);border:1px solid rgba(21,21,21,.14);border-radius:6px;
  box-shadow:0 14px 34px rgba(21,21,21,.10)}
#v-rr .silo .hd{display:flex;align-items:center;gap:8px;margin-bottom:9px}
#v-rr .silo .hd svg{width:14px;height:14px;color:var(--graphite);flex:0 0 auto}
