#v-rr .asks,#v-rr .adapts{border-radius:6px;padding:14px 16px}
#v-rr .asks{background:rgba(0,0,0,.5);border:1px solid rgba(244,241,232,.22)}
#v-rr .adapts{background:var(--signal);border:1px solid var(--signal)}
#v-rr .asks .lb,#v-rr .adapts .lb{font-size:var(--t-label);letter-spacing:.12em;text-transform:uppercase;
  font-weight:700;margin-bottom:7px}
#v-rr .asks .lb{color:rgba(244,241,232,.6)}
/* Paper is only 4.53:1 on Signal Cobalt, so it cannot be dimmed here */
#v-rr .adapts .lb{color:var(--paper)}
#v-rr .asks p:last-child{font-size:var(--t-small);line-height:1.45;color:var(--paper);transition:opacity .28s}
#v-rr .adapts p:last-child{font-size:var(--t-small);line-height:1.45;color:var(--paper);transition:opacity .28s}

/* row 3 */
#v-rr .jv-3{gap:0}
#v-rr .signal-card{flex:0 0 auto;background:var(--paper);border:1px solid rgba(21,21,21,.14);
  border-radius:6px;padding:16px 18px;min-width:0;max-width:390px}
#v-rr .sc-t{display:flex;align-items:center;font-size:var(--t-small);color:var(--ink)}
#v-rr .sc-d{font-size:var(--t-label);color:var(--graphite);margin:6px 0 12px}
#v-rr .signal-card dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:8px 16px;
  padding-top:12px;border-top:1px solid rgba(21,21,21,.12)}
#v-rr .signal-card dt{font-size:var(--t-label);color:var(--graphite);white-space:nowrap}
#v-rr .signal-card dd{font-size:var(--t-label);line-height:1.45;color:var(--ink);transition:opacity .28s}
#v-rr .receipts{flex:0 0 auto;display:flex;flex-direction:column;gap:8px;min-width:0}
#v-rr .rcpt{display:flex;align-items:center;gap:11px;background:var(--paper);
  border:1px solid rgba(21,21,21,.14);border-radius:6px;padding:11px 14px}
#v-rr .rcpt span{font-size:var(--t-small);color:var(--ink);transition:opacity .28s}

/* --- motion: each row assembles once, when it comes into view --- */
#v-rr .jv .ln{stroke-dasharray:1000;stroke-dashoffset:1000}
#v-rr .journey.in .jv .ln{animation:draw 1.1s cubic-bezier(.4,0,.2,1) forwards}
#v-rr .journey.in .jv-1 .ln:nth-of-type(2){animation-delay:.10s}
#v-rr .journey.in .jv-1 .ln:nth-of-type(3){animation-delay:.20s}
@keyframes draw{ to{ stroke-dashoffset:0 } }

#v-rr .src,#v-rr .node,#v-rr .ready,#v-rr .signal-card,#v-rr .rcpt,#v-rr .asks,#v-rr .adapts{opacity:0;transform:translateY(8px)}
#v-rr .journey.in .src,#v-rr .journey.in .node,#v-rr .journey.in .ready,#v-rr .journey.in .signal-card,#v-rr .journey.in .rcpt,#v-rr .journey.in .asks,#v-rr .journey.in .adapts{
  animation:rise .55s cubic-bezier(.4,0,.2,1) forwards}
@keyframes rise{ to{ opacity:1; transform:none } }
#v-rr .journey.in .src:nth-of-type(2){animation-delay:.07s}
#v-rr .journey.in .src:nth-of-type(3){animation-delay:.14s}
#v-rr .journey.in .node{animation-delay:.34s}
#v-rr .journey.in .ready{animation-delay:.62s}
#v-rr .journey.in .asks{animation-delay:.12s}
#v-rr .journey.in .adapts{animation-delay:.22s}
#v-rr .journey.in .signal-card{animation-delay:.06s}
#v-rr .journey.in .rcpt:nth-of-type(2){animation-delay:.16s}

/* the node keeps a slow breath, so the row reads as live rather than finished */
#v-rr .journey.in .node::after{content:"";position:absolute;inset:-6px;border-radius:50%;
  border:1px solid var(--signal);opacity:0;animation:breathe 3.6s ease-in-out .9s infinite}
@keyframes breathe{ 0%{opacity:.55;transform:scale(.92)} 60%{opacity:0;transform:scale(1.22)}
                    100%{opacity:0;transform:scale(1.22)} }

/* the stack marks the live reason with a travelling rule */
#v-rr .stack button{position:relative;padding-left:0}
#v-rr .stack button[aria-selected="true"]::before{content:"";position:absolute;left:-18px;top:50%;
  width:10px;height:1px;background:var(--signal);transform:translateY(-50%);
  animation:reach .4s cubic-bezier(.4,0,.2,1) forwards}
@keyframes reach{ from{ width:0; opacity:0 } to{ width:10px; opacity:1 } }

@media(prefers-reduced-motion:reduce){
  #v-rr .jv .ln{stroke-dasharray:none;stroke-dashoffset:0}
  #v-rr .src,#v-rr .node,#v-rr .ready,#v-rr .signal-card,#v-rr .rcpt,#v-rr .asks,#v-rr .adapts{opacity:1;transform:none;animation:none!important}
  #v-rr .journey.in .node::after{animation:none;opacity:0}
  #v-rr .stack button[aria-selected="true"]::before{animation:none;width:10px;opacity:1}
}
/* nothing hidden if the script never runs */
#v-rr .no-js .src,#v-rr .no-js .node,#v-rr .no-js .ready,#v-rr .no-js .signal-card,#v-rr .no-js .rcpt,#v-rr .no-js .asks,#v-rr .no-js .adapts{opacity:1;transform:none}
#v-rr .no-js .jv .ln{stroke-dashoffset:0}

@media(max-width:1080px){
  #v-rr .jv-1,#v-rr .jv-3{flex-wrap:wrap;gap:18px}
  #v-rr .conv,#v-rr .jv-out{display:none}
  #v-rr .sources{flex-direction:row;gap:18px;flex-wrap:wrap}
  #v-rr .src span{width:auto;text-align:left}
}
@media(max-width:900px){
  #v-rr .journey{grid-template-columns:1fr}
  #v-rr .jl{padding:clamp(22px,4vw,30px)}
  #v-rr .jv{border-left:0;padding:clamp(22px,4vw,30px)}
  #v-rr .journey > .jl:first-child + .jv{border-top:1px solid rgba(21,21,21,.14)}
  #v-rr .jv-2{flex-direction:column;align-items:stretch;gap:22px}
  #v-rr .side{flex:1 1 auto}
}
@media(prefers-reduced-motion:reduce){
  #v-rr .stack button,#v-rr .asks p,#v-rr .adapts p,#v-rr .signal-card dd,#v-rr .rcpt span{transition:none}
}

