  font-weight:400;color:var(--graphite);max-width:46ch;margin:0 auto clamp(40px,4.6vw,64px);
  text-align:center;text-wrap:balance}
#v-rr #rr-conn .wrapc > h2.lede-run b{font-weight:400;color:var(--ink)}

#v-rr .bento{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;
