#v-rr .bs-h{font-size:11.5px;color:#8A9199;margin-bottom:10px}
#v-rr .bs-r{display:flex;align-items:center;gap:10px;margin-bottom:6px}
#v-rr .bs-b{background:#E4EBFA;border-radius:6px;padding:7px 10px;font-size:12px;color:#1B2026;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
#v-rr .bs-r b{margin-left:auto;flex:0 0 auto;font-weight:400;font-size:12px;color:#8A9199;
  font-variant-numeric:tabular-nums}

/* payments: the checkout state */
#v-rr .pay-r{display:flex;justify-content:space-between;align-items:baseline;gap:10px;
  padding:8px 12px;border-bottom:1px solid rgba(21,21,21,.06);font-size:12.5px;color:#101418}
#v-rr .pay-r span{color:#8A9199}
#v-rr .tag{font-size:10.5px;border-radius:4px;padding:3px 8px;background:#EDEFF2;color:#6A7178}
#v-rr .mrow{display:flex;gap:7px;padding:10px 12px 8px}
#v-rr .mth{font-size:11.5px;border:1px solid rgba(21,21,21,.14);border-radius:6px;
  padding:6px 10px;color:#6A7178}
#v-rr .mth.on{border-color:#3b66d6;background:#EFF4FF;color:#3b66d6}
#v-rr .mini{display:block;margin:0 12px 12px;text-align:center;background:#101418;color:#fff;
  border-radius:7px;padding:10px;font-size:12px}

/* crm: what is connected */
#v-rr .intg{flex:1 1 auto;min-height:0;display:grid;grid-template-columns:repeat(3,1fr);
  gap:9px;padding:12px;align-content:start}
#v-rr .intg > span{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;
  height:62px;border:1px solid rgba(21,21,21,.08);border-radius:9px;background:#fff;
  box-shadow:0 1px 3px rgba(16,20,24,.05)}
#v-rr .intg .mk{width:19px;height:19px}
#v-rr .intg .mk.zo{width:44px;height:19px}
#v-rr .intg i{font-style:normal;font-size:10.5px;color:#8A9199}
#v-rr .intg-n{font-size:11.5px;line-height:1.5;color:#8A9199;padding:0 12px 12px}

@media(max-width:1000px){
  #v-rr .bento{grid-template-columns:1fr;max-width:560px}
  #v-rr .bt,#v-rr .bt:nth-child(2n),#v-rr .bt:nth-last-child(-n+2){height:auto;min-height:0;padding-bottom:20px;
    border-right:0;border-bottom:1px solid rgba(21,21,21,.09)}
  #v-rr .bt:last-child{border-bottom:0}
  #v-rr .ui.clip::after{display:none}
}
@media(prefers-reduced-motion:reduce){ #v-rr .wa-typ i{animation:none} }

/* --- 7 deployment: four stages, in order --- */
/* Continues the bento's light ground rather than cutting to black between the
   two, then makes the one descent into the dark closing panel. */
#v-rr #rr-deploy{
  background:#E8EDFF;
  padding:clamp(72px,7vw,108px) 0 clamp(56px,5vw,88px)}
#v-rr #rr-deploy .wrapc > h2{color:var(--ink);white-space:nowrap;max-width:none;
  line-height:1.3;margin:0 auto clamp(24px,2.6vw,34px)}
#v-rr #rr-deploy .wrapc > .lede{color:var(--graphite);white-space:nowrap;max-width:none;
  line-height:1.75}
/* one line while there is room; below that they would run off the page */
@media(max-width:1400px){
  #v-rr #rr-deploy .wrapc > .lede{white-space:normal;max-width:74ch;text-wrap:balance}
}
@media(max-width:1080px){
  #v-rr #rr-deploy .wrapc > h2{white-space:normal;max-width:34ch;text-wrap:balance}
}
#v-rr #rr-deploy .close-line{color:var(--graphite);border-left-color:var(--signal)}
/* Define, Connect, Test, Operate is a real sequence, so the cells are numbered
   and share hairlines the way the bento above them does. On Jet the copy runs
   at Paper 66%; Graphite would fail here. */
#v-rr .stages{list-style:none;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;
  margin:clamp(54px,5.8vw,82px) auto 0;max-width:1060px;
  background:#fff;border:1px solid rgba(21,21,21,.09);border-radius:6px;overflow:hidden}
#v-rr .stages > li{display:flex;flex-direction:column;
  padding:clamp(22px,2.4vw,30px) clamp(18px,2vw,25px);
  border-right:1px solid rgba(21,21,21,.09)}
#v-rr .stages > li:last-child{border-right:0}
#v-rr .stages .sn{font-size:var(--t-label);letter-spacing:.16em;color:var(--deep);
  font-variant-numeric:tabular-nums;margin-bottom:clamp(20px,2.4vw,32px)}
#v-rr .stages h3{font-size:var(--t-h3);line-height:1.25;font-weight:400;color:var(--ink);
  margin-bottom:10px}
#v-rr .stages p{font-size:var(--t-small);line-height:1.55;color:var(--graphite)}
#v-rr #rr-deploy .close-line{width:min(1060px,100%);max-width:none;
  margin:clamp(30px,3.4vw,44px) auto 0}

@media(max-width:980px){
  #v-rr .stages{grid-template-columns:repeat(2,minmax(0,1fr))}
  #v-rr .stages > li:nth-child(2n){border-right:0}
  #v-rr .stages > li:nth-child(-n+2){border-bottom:1px solid rgba(21,21,21,.09)}
}
/* --- 8 final cta --- */
/* The light field is painted to canvas; the section only has to hold it and
   centre the copy over it. Without these the canvas stays at its 300x150
   intrinsic size and never paints. */
#v-rr #rr-cta{position:relative;z-index:2;overflow:hidden;
  background:linear-gradient(180deg,#E8EDFF 0%,#E8EDFF 54%,#F4F1E8 100%)}
#v-rr #rr-cta .in{position:relative;z-index:1;width:100%;text-align:center;
  max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;
  padding:clamp(124px,13vw,188px) var(--pad-x)}
#v-rr #rr-cta h2{color:var(--ink);line-height:1.3;margin:0 auto clamp(26px,3vw,38px);
  max-width:24ch;text-wrap:balance}
#v-rr #rr-cta .lede{color:var(--graphite);line-height:1.7;max-width:52ch;
  margin:0 auto clamp(42px,4.8vw,62px);text-align:center;text-wrap:balance}
#v-rr #rr-cta .btn-solid{background:var(--jet);color:var(--paper)}

@media(max-width:620px){
  #v-rr .stages{grid-template-columns:1fr}
  #v-rr .stages > li,#v-rr .stages > li:nth-child(2n){border-right:0;
    border-bottom:1px solid rgba(21,21,21,.09)}
  #v-rr .stages > li:last-child{border-bottom:0}
}

/* --- journey: the checkout and the three rows are one component --------
   The screenshot holds the left column across all three rows; the visuals
   run down the right. One border, one box, one idea. */
#v-rr #rr-thesis .journey{grid-template-columns:minmax(0,.48fr) minmax(0,.52fr);
  margin-top:clamp(30px,4vw,52px)}
#v-rr #rr-thesis .journey > .cartshot{
  grid-column:1;grid-row:1 / span 3;margin:0;max-width:none;
  border:0;border-right:1px solid rgba(21,21,21,.14);border-radius:0;
  background:var(--paper);display:flex;flex-direction:column;justify-content:center;
  padding:clamp(18px,2vw,28px)}
#v-rr #rr-thesis .journey > .cartshot img{display:block;width:100%;height:auto;
  border:1px solid rgba(21,21,21,.10);border-radius:4px}
#v-rr #rr-thesis .journey > .cartshot figcaption{margin-top:clamp(12px,1.6vw,18px);
  font-size:var(--t-small);line-height:1.5;color:var(--graphite);text-align:center}
#v-rr #rr-thesis .journey > .jv{grid-column:2;border-left:0;
  border-top:1px solid rgba(21,21,21,.14)}
#v-rr #rr-thesis .journey > div.jv:nth-of-type(1){grid-row:1;border-top:0}
#v-rr #rr-thesis .journey > div.jv:nth-of-type(2){grid-row:2}
#v-rr #rr-thesis .journey > div.jv:nth-of-type(3){grid-row:3}

@media(max-width:900px){
  #v-rr #rr-thesis .journey{grid-template-columns:1fr}
  #v-rr #rr-thesis .journey > .cartshot{grid-column:1;grid-row:1;
    border-right:0;border-bottom:1px solid rgba(21,21,21,.14)}
  #v-rr #rr-thesis .journey > .jv{grid-column:1}
  #v-rr #rr-thesis .journey > div.jv:nth-of-type(1){grid-row:2;border-top:0}
  #v-rr #rr-thesis .journey > div.jv:nth-of-type(2){grid-row:3}
  #v-rr #rr-thesis .journey > div.jv:nth-of-type(3){grid-row:4}
}

/* ===================== FOOTER ===================== */
#v-rr #rrfoot{position:relative;z-index:2;background:var(--paper)}
#v-rr #rrfoot .ft-wrap{
  max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;
  padding:clamp(56px,7vw,96px) var(--pad-x) clamp(28px,3vw,40px)
}
#v-rr #rrfoot .ft-top{
  display:grid;grid-template-columns:minmax(0,1fr) auto;gap:clamp(32px,6vw,96px);
  align-items:start;padding-bottom:clamp(40px,5vw,72px)
}
#v-rr #rrfoot .ft-mark{display:block;line-height:0}
#v-rr #rrfoot .ft-mark svg{display:block;margin:0;width:clamp(132px,14vw,188px);height:auto}
#v-rr #rrfoot .ft-cols{display:grid;grid-template-columns:repeat(2,minmax(120px,1fr));gap:clamp(32px,5vw,80px)}
#v-rr #rrfoot .ft-cols p{
  font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  color:var(--graphite);margin-bottom:16px
}
#v-rr #rrfoot .ft-cols a{
  display:block;font-size:var(--t-small);line-height:1.5;color:var(--ink);
  margin-bottom:11px;transition:color .3s
}
#v-rr #rrfoot .ft-cols a:hover{color:var(--deep)}
#v-rr #rrfoot .ft-bar{
  display:flex;align-items:center;gap:clamp(16px,3vw,40px);flex-wrap:wrap;
  padding-top:clamp(20px,2.4vw,30px);border-top:1px solid rgba(21,21,21,.14)
}
#v-rr #rrfoot .ft-legal{font-size:var(--t-label);color:var(--graphite)}
#v-rr #rrfoot .ft-links{display:flex;gap:clamp(14px,2vw,26px)}
#v-rr #rrfoot .ft-links a{font-size:var(--t-label);color:var(--graphite);transition:color .3s}
#v-rr #rrfoot .ft-links a:hover{color:var(--deep)}
#v-rr #rrfoot .ft-social{display:flex;gap:14px;margin-left:auto}
#v-rr #rrfoot .ft-social a{
  width:18px;height:18px;display:block;color:var(--graphite);transition:color .3s
}
#v-rr #rrfoot .ft-social a:hover{color:var(--deep)}
#v-rr #rrfoot .ft-social svg{width:100%;height:100%;display:block}

@media(max-width:700px){
  #v-rr #rrfoot .ft-top{grid-template-columns:1fr;gap:36px}
  #v-rr #rrfoot .ft-social{margin-left:0}
}

@media(prefers-reduced-motion:reduce){}

/* ---------- appended last, so nothing upstream can swallow it ----------
   NB: a previous edit here used a lookahead that ran past this block and
   deleted the two-column silos rule. Keep additions at the very end. */

/* the loop sits left, the caller photograph takes the space on the right */
#v-rr .silos{aspect-ratio:auto;display:grid;
  grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);
  gap:clamp(20px,3vw,52px);align-items:center;max-width:1160px}
#v-rr .loopwrap{position:relative;aspect-ratio:620/470;min-height:330px}
#v-rr .silos .silo{width:clamp(140px,13vw,178px);padding:12px 14px}
#v-rr .silos .agent{width:clamp(118px,11vw,150px)}
#v-rr .caller{border:1px solid rgba(21,21,21,.14);border-radius:6px;background:var(--paper);
  padding:clamp(16px,2vw,24px) clamp(16px,2vw,24px) clamp(12px,1.4vw,16px);margin:0}
#v-rr .caller img{display:block;width:100%;height:auto;border-radius:4px;
  aspect-ratio:4/3;object-fit:cover;object-position:50% 34%}
#v-rr .caller figcaption{margin-top:clamp(10px,1.4vw,16px);text-align:center;
  font-size:var(--t-small);line-height:1.5;color:var(--graphite)}
@media(max-width:900px){
  #v-rr .silos{grid-template-columns:1fr;gap:22px}
  #v-rr .loopwrap{aspect-ratio:auto;min-height:0}
  #v-rr .caller{order:-1}
}

/* the journey reads as one surface, not a framed box, and the checkout
   fills its column so it squares off against the three rows beside it.
   Cropping right-of-centre keeps Payment Method and Order Summary -- the
   part the caption is actually about -- and loses the address form. */
#v-rr #rr-thesis .journey{border:0;border-radius:0;column-gap:clamp(18px,2.2vw,36px)}
#v-rr #rr-thesis .journey > .cartshot{padding:0;border-right:0;background:transparent;
  display:flex;flex-direction:column;justify-content:flex-start;min-height:0}
#v-rr #rr-thesis .journey > .cartshot img{border:0;flex:1 1 auto;min-height:0;
  width:100%;height:100%;object-fit:cover;object-position:100% 50%;border-radius:6px}
#v-rr #rr-thesis .journey > .cartshot figcaption{flex:0 0 auto;margin-top:clamp(12px,1.5vw,18px)}

/* deployment: no frame, and it uses the width the rest of the page uses.
   The photograph fills its column edge to edge rather than floating in a
   padded card, and the four stages sit two-up beside it. */
#v-rr .depwrap{display:grid;grid-template-columns:minmax(0,.46fr) minmax(0,.54fr);
  gap:clamp(20px,2.6vw,44px);align-items:stretch;
  margin:clamp(46px,5vw,74px) auto 0;max-width:none;width:100%;
  background:transparent;border:0;border-radius:0;overflow:visible}
#v-rr .devshot{margin:0;padding:0;border:0;background:transparent;
  display:flex;flex-direction:column;min-height:0}
#v-rr .devshot img{display:block;width:100%;flex:1 1 auto;min-height:280px;
  object-fit:cover;object-position:38% 50%;border-radius:6px}
#v-rr .devshot figcaption{flex:0 0 auto;margin-top:clamp(12px,1.5vw,18px);text-align:center;
  font-size:var(--t-small);line-height:1.5;color:var(--graphite)}
#v-rr .depwrap .stages{margin:0;max-width:none;border:0;border-radius:0;
  grid-template-columns:repeat(2,minmax(0,1fr));align-self:stretch}
#v-rr .depwrap .stages > li{padding:clamp(20px,2.2vw,30px) clamp(18px,2vw,28px);
  border-right:1px solid rgba(21,21,21,.12);
  border-bottom:1px solid rgba(21,21,21,.12)}
#v-rr .depwrap .stages > li:nth-child(2n){border-right:0}
#v-rr .depwrap .stages > li:nth-last-child(-n+2){border-bottom:0}

@media(max-width:900px){
  #v-rr .depwrap{grid-template-columns:1fr;gap:24px}
  #v-rr .devshot img{min-height:220px}
  #v-rr .depwrap .stages{grid-template-columns:1fr}
  #v-rr .depwrap .stages > li{border-right:0;border-bottom:1px solid rgba(21,21,21,.12)}
  #v-rr .depwrap .stages > li:last-child{border-bottom:0}
}

/* one continuous background field for the whole page, no per-section canvases,
   so there is no seam where two compositions meet */
#v-ent #pagebg{position:absolute;top:0;left:0;width:100%;z-index:0;display:block;pointer-events:none}

/* ---------- shared button language, radius 2px, never pills ---------- */
#v-ent .btn{
  display:inline-block;font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  padding:14px 28px;border-radius:2px;border:1px solid transparent;cursor:pointer;
}
#v-ent .btn-solid{background:var(--paper);color:var(--jet);font-weight:700}
#v-ent .btn-ghost{border-color:var(--hairline);color:var(--paper);background:none}

/* ============================ HEADER ============================ */
#v-ent .site-head{position:relative;z-index:2;height:66px;flex:0 0 auto}
#v-ent .site-head .mark{position:absolute;left:var(--pad-x);top:50%;transform:translateY(-50%);line-height:0}
#v-ent .site-head .mark svg{display:block;margin:0}
#v-ent .site-head nav{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  display:flex;gap:30px;font-size:var(--t-small);white-space:nowrap
}
#v-ent .site-head .actions{
  position:absolute;right:var(--pad-x);top:50%;transform:translateY(-50%);
  display:flex;gap:8px;align-items:center
}
#v-ent .site-head .actions .talk{color:rgba(244,241,232,.8);font-size:var(--t-small)}
#v-ent .site-head .actions .login{
  background:var(--paper);color:var(--jet);font-size:var(--t-label);font-weight:700;
  letter-spacing:.08em;text-transform:uppercase;padding:9px 16px;border-radius:2px
}
@media(max-width:700px){ #v-ent .site-head nav{display:none} }

/* ===================== REVENUE RECOVERY, page shell ===================== */
#v-ent #pagebg{position:absolute;top:0;left:0;width:100%;z-index:0;display:block;pointer-events:none}
#v-ent .sec{position:relative;z-index:2}
#v-ent .wrapc{max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;padding:0 var(--pad-x)}
#v-ent .kick{font-size:var(--t-label);letter-spacing:.14em;text-transform:uppercase;color:rgba(244,241,232,.6)}
#v-ent .sec h2{font-size:var(--t-h2);line-height:var(--lh-h2);letter-spacing:-.012em;font-weight:400;
  margin:14px 0 14px;max-width:24ch}
#v-ent .sec .lede{font-size:var(--t-lead);line-height:var(--lh-lead);color:var(--fg-2);max-width:60ch}
#v-ent .sec .close-line{font-size:var(--t-small);color:rgba(244,241,232,.6);margin-top:26px;
  border-left:2px solid var(--signal);padding-left:14px;max-width:64ch}
#v-ent .pad{padding:clamp(64px,8vw,120px) 0}

/* ===================== ENTERPRISE =====================
   Structure and motion follow the reference: a dark ground washed with the
   brand blue at every transition, oversized two-tone headlines, product
   panels tilted hard in 3-D, drifting connector marks and a glowing call to
   action. Palette and type are Truffl's -- Jet, Signal Cobalt, Paper, Arial. */
#v-ent #v-ent-scope{}
#v-ent #en-hero,#v-ent #en-vigs,#v-ent #en-conn,#v-ent #en-duo,#v-ent #en-caps,#v-ent #en-cta{position:relative;z-index:2}

/* ---------- hero ---------- */
#v-ent #en-hero{min-height:100vh;display:flex;flex-direction:column;overflow:hidden;
  color:var(--paper);background:
    /* resolve to black at the very bottom so the next section joins invisibly */
    linear-gradient(180deg, rgba(0,0,0,0) 76%, rgba(0,0,0,.5) 91%, #000000 100%),
    radial-gradient(120% 60% at 50% 94%, rgba(49,92,255,.60) 0%, rgba(24,56,168,.24) 40%, rgba(0,0,0,0) 72%),
    radial-gradient(80% 50% at 50% -10%, rgba(49,92,255,.18) 0%, rgba(0,0,0,0) 70%),
    #000000}
#v-ent #en-hero .hero-in{flex:1 1 auto;display:flex;flex-direction:column;justify-content:center;
  text-align:center;width:100%;margin-inline:auto;position:relative;z-index:3;
  max-width:calc(var(--content) + var(--pad-x)*2);
  padding:clamp(40px,6vw,80px) var(--pad-x) clamp(90px,12vh,150px)}
/* one line across: the natural width is ~26.3x the font size, so the cap
   is what fits the 1440 column. Below 900px it has to wrap. */
#v-ent #en-hero h1{font-size:clamp(30px,3.45vw,54px);line-height:1.08;letter-spacing:-.024em;
  font-weight:400;margin:0 auto 26px;max-width:none;white-space:nowrap;color:var(--paper)}
@media(max-width:900px){
  #v-ent #en-hero h1{white-space:normal;font-size:clamp(32px,6vw,46px);max-width:18ch;text-wrap:balance}
}
#v-ent #en-hero .sub{font-size:var(--t-lead);line-height:var(--lh-lead);
  color:rgba(244,241,232,.82);max-width:60ch;margin:0 auto 40px;text-wrap:balance}
#v-ent #en-hero .ctas{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;align-items:center}
#v-ent #en-hero .kick{color:var(--paper);margin-bottom:22px}

/* the glowing primary, as in the reference */
#v-ent .btn-glow{position:relative;display:inline-flex;align-items:center;gap:9px;
  font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;font-weight:700;
  padding:15px 30px;border-radius:2px;background:var(--paper);color:var(--jet);z-index:1}
#v-ent .btn-glow::before{content:"";position:absolute;inset:-16px;border-radius:14px;z-index:-1;
  background:radial-gradient(closest-side, rgba(49,92,255,.85), rgba(24,56,168,.35) 55%, rgba(0,0,0,0) 78%);
  filter:blur(14px);animation:glowPulse 3.6s ease-in-out infinite}
@keyframes glowPulse{0%,100%{opacity:.75;transform:scale(1)}50%{opacity:1;transform:scale(1.09)}}
#v-ent .btn-line{font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  color:rgba(244,241,232,.82);border:1px solid rgba(244,241,232,.28);
  border-radius:2px;padding:15px 26px}
#v-ent #en-cta .btn-glow{background:var(--ink);color:var(--paper)}
#v-ent #en-cta .btn-glow::before{inset:-26px;filter:blur(20px);
  background:radial-gradient(closest-side, rgba(49,92,255,.95), rgba(24,56,168,.45) 52%, rgba(0,0,0,0) 78%)}
#v-ent #en-cta .btn-line{color:var(--ink);border-color:rgba(21,21,21,.3)}

#v-ent .tiltwrap .t i:nth-child(1){top:16%}
/* ---------- hero scene: the systems falling through the field ----------
   A single plane tilted in 3-D. Everything on it travels the same axis, so
   in screen space the tiles and panels read as drifting diagonally past the
   viewer. A scrim keeps the headline legible over the top of it. */
#v-ent #en-hero .herobg{position:absolute;inset:0;z-index:1;overflow:hidden;pointer-events:none;
  perspective:1150px;perspective-origin:64% 16%}
#v-ent .hb-plane{position:absolute;left:-26%;top:-46%;width:152%;height:192%;
  transform-style:preserve-3d;transform:rotateX(46deg) rotateZ(-23deg)}
#v-ent .hb-lane{position:absolute;top:0;height:100%;width:150px}
#v-ent .hb-lane.l1{left:22%}#v-ent .hb-lane.l2{left:40%}#v-ent .hb-lane.l3{left:58%}#v-ent .hb-lane.l4{left:76%}
#v-ent .hb-lane::before{content:"";position:absolute;left:50%;top:-10%;height:120%;width:1px;
  background:linear-gradient(180deg,rgba(244,241,232,0),rgba(244,241,232,.16),rgba(244,241,232,0))}
#v-ent .hb-item{position:absolute;top:0;left:50%;margin-left:-38px;width:76px;height:76px;border-radius:18px;
  display:grid;place-items:center;
  background:linear-gradient(180deg,rgba(32,35,46,.97),rgba(13,15,21,.97));
  border:1px solid rgba(244,241,232,.15);
  box-shadow:0 30px 70px rgba(0,0,0,.72);
  animation:hbFall linear infinite}
#v-ent .hb-item svg{width:34px;height:34px;color:var(--paper);opacity:.92}
/* travel in viewport units: a percentage here would resolve against the
   tile's own height, so a 76px tile would barely move at all */
/* the falling panels carry real workspace content, not placeholder bars */
#v-ent .hb-p{position:absolute;top:0;left:50%;border-radius:14px;
  background:linear-gradient(180deg,rgba(26,29,39,.975),rgba(11,13,19,.975));
  border:1px solid rgba(244,241,232,.13);box-shadow:0 42px 92px rgba(0,0,0,.76);
  overflow:hidden;animation:hbFall linear infinite;
  font-family:var(--font);
  color:rgba(244,241,232,.9)}
#v-ent .hb-p .hd{display:flex;align-items:center;gap:7px;padding:9px 12px;
  border-bottom:1px solid rgba(244,241,232,.09);background:rgba(244,241,232,.03);
  font-size:11px;color:rgba(244,241,232,.72)}
#v-ent .hb-p .hd .r{margin-left:auto;font-size:9.5px;letter-spacing:.06em;text-transform:uppercase;
  color:#9FB4FF}
#v-ent .hb-p .bd{padding:11px 12px}
#v-ent .hb-p .ln{display:flex;gap:8px;align-items:baseline;font-size:10.5px;line-height:1.5;
  padding:5px 0;border-top:1px solid rgba(244,241,232,.07)}
#v-ent .hb-p .ln:first-child{border-top:0}
#v-ent .hb-p .ln .k{color:rgba(244,241,232,.45);width:62px;flex:0 0 auto}
#v-ent .hb-p .ln .v{color:rgba(244,241,232,.88)}
#v-ent .hb-p .ln .t{margin-left:auto;color:rgba(244,241,232,.36);font-size:9.5px}
#v-ent .hb-p .av{width:17px;height:17px;border-radius:50%;flex:0 0 auto;display:grid;place-items:center;
  font-size:8.5px;color:#0B0D13;background:#9FB4FF}
#v-ent .hb-p .quote{font-size:11.5px;line-height:1.5;color:rgba(244,241,232,.92);margin-bottom:8px}
#v-ent .hb-p .sub{font-size:10px;color:rgba(244,241,232,.5)}
#v-ent .hb-p .pill{display:inline-block;font-size:9px;letter-spacing:.05em;text-transform:uppercase;
  padding:2px 7px;border-radius:4px;background:rgba(49,92,255,.18);color:#9FB4FF;
  border:1px solid rgba(49,92,255,.34)}
#v-ent .hb-p .nav{font-size:10.5px;line-height:2.1;color:rgba(244,241,232,.62)}
#v-ent .hb-p .nav b{display:block;font-weight:400;color:rgba(244,241,232,.95)}
#v-ent .hb-p .nav i{font-style:normal;display:block;color:rgba(244,241,232,.34);
  font-size:9px;letter-spacing:.1em;text-transform:uppercase;margin:7px 0 2px}
#v-ent .hb-p .wave{display:flex;align-items:flex-end;gap:2px;height:22px;margin:8px 0}
#v-ent .hb-p .wave i{flex:1 1 auto;background:rgba(49,92,255,.55);border-radius:1px}
#v-ent .hb-w300{width:300px;margin-left:-150px}
#v-ent .hb-w260{width:260px;margin-left:-130px}

@keyframes hbFall{
  0%{transform:translateY(-40vh) translateZ(0);opacity:0}
  7%{opacity:1}
  90%{opacity:1}
  100%{transform:translateY(170vh) translateZ(0);opacity:0}
}
/* keeps the copy readable over the moving field */
#v-ent #en-hero .scrim{position:absolute;inset:0;z-index:2;pointer-events:none;background:
  radial-gradient(60% 46% at 50% 58%, rgba(0,0,0,.90) 0%, rgba(0,0,0,.70) 46%, rgba(0,0,0,.18) 80%, rgba(0,0,0,0) 100%),
  linear-gradient(180deg, rgba(0,0,0,.55) 0%, rgba(0,0,0,0) 26%, rgba(0,0,0,0) 62%, rgba(0,0,0,.55) 100%)}
@media(max-width:900px){ #v-ent #en-hero .herobg{opacity:.5} }
@media(prefers-reduced-motion:reduce){
  #v-ent .hb-item,#v-ent .hb-p{animation:none;opacity:.85}
}

/* ===================== 2 · FEATURE GRID =====================
   Template follows the reference: a two-column grid split by hairlines, each
   cell a two-tone headline over a product mock, closed by a full-width block
   on a colour wash with tilted cards. Wash is Signal/Deep Cobalt.
   NB: text alphas are >=.58 (AA on this ground); background and border alphas
   are deliberately low -- do not lift them together. */
#v-ent #en-vigs{overflow:hidden;background:
  radial-gradient(74% 38% at 8% 30%, rgba(49,92,255,.14) 0%, rgba(0,0,0,0) 64%),
  radial-gradient(60% 32% at 92% 66%, rgba(24,56,168,.12) 0%, rgba(0,0,0,0) 62%),
  linear-gradient(180deg,#000000 0%,#000000 8%,#06070C 34%,#06070C 62%,#000000 100%)}
#v-ent .fgrid{max-width:min(calc(var(--content) + var(--pad-x)*2), 92vw);margin-inline:auto;
  padding-inline:var(--pad-x);
  display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}
#v-ent .fcell{padding:clamp(64px,7.5vw,128px) clamp(30px,5vw,86px);
  position:relative;overflow:hidden}
/* the right column runs lower than the left, so the pairs read as offset
   rather than as a rigid 2x2 -- misaligned, but on the same rhythm */
#v-ent .fcell:nth-child(2n){margin-top:clamp(60px,9vw,170px)}
#v-ent .fcell:nth-child(2n+3){margin-top:clamp(-60px,-9vw,-170px)}
#v-ent .fh{font-size:clamp(24px,2.5vw,38px);line-height:1.16;letter-spacing:-.014em;font-weight:400;
  color:rgba(244,241,232,.58);margin-bottom:clamp(28px,3.2vw,46px);max-width:23ch;
  text-wrap:balance;opacity:0;transform:translateY(14px);transition:opacity .7s,transform .7s}
#v-ent .fh b{font-weight:400;color:var(--paper)}
#v-ent .fcell.in .fh,#v-ent .fwide.in .fh{opacity:1;transform:none}
#v-ent .fmock{opacity:0;transform:translateY(20px);transition:opacity .85s .1s,transform .85s .1s}
#v-ent .fcell.in .fmock,#v-ent .fwide.in .fmock{opacity:1;transform:none}

#v-ent .m{background:linear-gradient(180deg,#15171F,#0B0D13);border:1px solid rgba(244,241,232,.12);
  border-radius:12px;box-shadow:0 34px 76px rgba(0,0,0,.66);overflow:hidden;
  font-family:var(--font);
  color:var(--paper)}
#v-ent .m-hd{display:flex;align-items:center;gap:10px;padding:13px 15px;font-size:13px;
  border-bottom:1px solid rgba(244,241,232,.09)}
#v-ent .m-hd .av{width:24px;height:24px;border-radius:50%;background:var(--signal);color:var(--paper);
  display:grid;place-items:center;font-size:11px;flex:0 0 auto}
#v-ent .m-hd .close{margin-left:auto;font-size:11.5px;border:1px solid rgba(244,241,232,.2);
  border-radius:6px;padding:5px 12px;color:rgba(244,241,232,.78)}
#v-ent .m-bd{padding:15px}
#v-ent .m-row{display:flex;align-items:center;gap:10px;font-size:12.5px;color:rgba(244,241,232,.9)}
#v-ent .m-row .tm{margin-left:auto;color:rgba(244,241,232,.62);font-size:11.5px}
#v-ent .m-wave{display:flex;align-items:center;gap:2.5px;height:40px;margin:14px 0 10px}
#v-ent .m-wave i{flex:1 1 auto;border-radius:2px;
  background:linear-gradient(180deg,var(--signal),rgba(49,92,255,.35));
  animation:mwave 1.5s ease-in-out infinite}
@keyframes mwave{0%,100%{transform:scaleY(.42)}50%{transform:scaleY(1)}}
#v-ent .m-foot{display:flex;align-items:center;gap:10px;font-size:11.5px;color:rgba(244,241,232,.66)}
#v-ent .m-foot .live{margin-left:auto;color:var(--pale)}
#v-ent .m-pill{display:inline-flex;align-items:center;gap:9px;margin-top:16px;
  border:1px solid rgba(244,241,232,.24);border-radius:999px;padding:9px 16px;
  font-size:12px;color:var(--paper);background:#0B0D13}
#v-ent .m-pill span{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;
  background:var(--deep);border:1px solid var(--signal);color:var(--paper);font-size:11px}

#v-ent .tilted{perspective:1500px;perspective-origin:20% 40%;margin-right:clamp(-130px,-8vw,-40px)}
#v-ent .tilted .m{transform:rotateY(-16deg) rotateX(7deg) rotateZ(-3deg)}
#v-ent .m-list .r{display:grid;grid-template-columns:24px minmax(0,1fr) auto;gap:10px;align-items:center;
  padding:11px 0;border-top:1px solid rgba(244,241,232,.08);font-size:12.5px}
#v-ent .m-list .r:first-child{border-top:0}
#v-ent .m-list .r .av{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;
  font-size:10px;color:#0B0D13;background:var(--pale)}
#v-ent .m-list .r b{font-weight:400;display:block;color:var(--paper)}
#v-ent .m-list .r i{font-style:normal;display:block;font-size:11px;color:rgba(244,241,232,.62)}
#v-ent .m-list .r .tm{font-size:11px;color:rgba(244,241,232,.6)}
#v-ent .m-sub{display:flex;gap:14px;font-size:11.5px;color:rgba(244,241,232,.62);
  padding:0 15px 12px;border-bottom:1px solid rgba(244,241,232,.08)}
#v-ent .m-sub .n{margin-left:auto}

#v-ent .msg{border:1px solid rgba(244,241,232,.12);border-radius:12px;padding:14px 16px;
  background:linear-gradient(180deg,#15171F,#0B0D13);box-shadow:0 26px 56px rgba(0,0,0,.6)}
#v-ent .msg + .msg{margin-top:-14px}
#v-ent .msg:nth-child(1){margin-left:26px;opacity:.7}
#v-ent .msg:nth-child(2){margin-left:6px;z-index:2;position:relative}
#v-ent .msg:nth-child(3){margin-left:0;z-index:3;position:relative}
#v-ent .msg .ch{display:flex;align-items:center;gap:8px;font-size:11px;
  color:rgba(244,241,232,.62);margin-bottom:9px}
#v-ent .msg .ch svg{width:14px;height:14px;color:rgba(244,241,232,.78)}
#v-ent .msg p{font-size:12.5px;line-height:1.6;color:rgba(244,241,232,.9)}

#v-ent .m-fields .f{display:grid;grid-template-columns:88px minmax(0,1fr);gap:10px;
  padding:10px 0;border-top:1px solid rgba(244,241,232,.08);font-size:12.5px}
#v-ent .m-fields .f:first-child{border-top:0}
#v-ent .m-fields .f span{color:rgba(244,241,232,.62)}
#v-ent .m-fields .f b{font-weight:400;color:var(--paper)}
#v-ent .langbox{position:relative}
#v-ent .langmenu{position:absolute;right:8px;top:44%;width:210px;z-index:3;
  background:#12141B;border:1px solid rgba(244,241,232,.18);
  border-radius:10px;box-shadow:0 30px 70px rgba(0,0,0,.78);padding:7px;font-size:12.5px}
#v-ent .langmenu .s{font-size:11.5px;color:rgba(244,241,232,.6);padding:7px 9px 9px}
#v-ent .langmenu .o{display:flex;align-items:center;gap:9px;padding:8px 9px;border-radius:6px;
  color:rgba(244,241,232,.86)}
#v-ent .langmenu .o.on{background:var(--deep);color:var(--paper)}
#v-ent .langmenu .o em{font-style:normal;color:var(--pale);width:12px}

/* the closing block: two overlapping cards on the wash, each with an action
   row and a trailing status pill -- the reference composition, in cobalt */
#v-ent .fwide{position:relative;overflow:hidden;
  background:
    radial-gradient(90% 70% at 26% 104%, rgba(49,92,255,.52) 0%, rgba(24,56,168,.24) 42%, rgba(0,0,0,0) 74%),
    radial-gradient(62% 54% at 84% 92%, rgba(24,56,168,.40) 0%, rgba(0,0,0,0) 66%)}
#v-ent .fwide .in-w{max-width:min(calc(var(--content) + var(--pad-x)*2), 92vw);margin-inline:auto;
  padding:clamp(64px,7.5vw,120px) calc(var(--pad-x) + clamp(30px,5vw,86px))
          clamp(100px,11vw,190px)}
#v-ent .fwide .fh{max-width:26ch}
#v-ent .cardstack{position:relative;height:clamp(360px,34vw,520px);perspective:1600px;
  perspective-origin:32% 44%}
#v-ent .cardstack .c{position:absolute;border-radius:16px;padding:22px 24px;background:#101219;
  border:1px solid rgba(244,241,232,.13);box-shadow:0 50px 110px rgba(0,0,0,.74)}
#v-ent .cardstack .c1{left:2%;top:20%;width:min(44%,392px);
  transform:rotateY(16deg) rotateX(10deg) rotateZ(-7deg)}
#v-ent .cardstack .c2{left:30%;top:0;width:min(46%,410px);
  transform:rotateY(14deg) rotateX(9deg) rotateZ(-5deg)}
#v-ent .cardstack .f{padding:11px 0;border-top:1px solid rgba(244,241,232,.08)}
#v-ent .cardstack .f:first-child{border-top:0;padding-top:0}
#v-ent .cardstack .f span{display:block;font-size:11.5px;color:rgba(244,241,232,.62);margin-bottom:3px}
#v-ent .cardstack .f b{display:block;font-weight:400;font-size:14px;color:var(--paper)}
#v-ent .cardstack .appr{display:flex;align-items:center;justify-content:flex-end;gap:8px;
  margin-top:8px;font-size:11.5px;color:rgba(244,241,232,.66)}
#v-ent .cardstack .appr i{width:20px;height:20px;border-radius:50%;background:var(--signal);
  color:var(--paper);display:grid;place-items:center;font-style:normal;font-size:9.5px}
#v-ent .cardstack .act{display:flex;align-items:center;gap:10px;margin-top:14px;padding-top:14px;
  border-top:1px solid rgba(244,241,232,.1);font-size:13.5px;color:var(--paper)}
#v-ent .cardstack .act svg{width:17px;height:17px;color:var(--pale);flex:0 0 auto}
#v-ent .cardstack .go{position:absolute;right:-18px;bottom:22px;width:34px;height:34px;border-radius:50%;
  background:#0B0D13;border:1px solid rgba(244,241,232,.22);color:var(--paper);
  display:grid;place-items:center;font-size:12px}
#v-ent .cardstack .pill{position:absolute;font-size:12.5px;background:#0B0D13;
  border:1px solid rgba(244,241,232,.2);border-radius:999px;padding:10px 18px;
  color:var(--paper);white-space:nowrap}
#v-ent .cardstack .p1{left:12%;bottom:1%;transform:rotateY(16deg) rotateZ(-7deg)}
#v-ent .cardstack .p2{left:40%;top:62%;transform:rotateY(14deg) rotateZ(-5deg)}

@media(max-width:1000px){
  #v-ent .fgrid{grid-template-columns:1fr}
  #v-ent .fcell,#v-ent .fcell:nth-child(2n),#v-ent .fcell:nth-child(2n+3){margin-top:0}
  #v-ent .tilted{perspective:none;margin-right:0}
  #v-ent .tilted .m{transform:none}
  #v-ent .cardstack{height:auto;perspective:none}
  #v-ent .cardstack .c,#v-ent .cardstack .note{position:static;width:auto;transform:none;margin-bottom:14px}
}
@media(prefers-reduced-motion:reduce){
  #v-ent .fh,#v-ent .fmock{opacity:1;transform:none;transition:none}
  #v-ent .m-wave i{animation:none;transform:scaleY(.7)}
}

/* ===================== 3 · THE APPROACH =====================
   Reference: a light section that opens with a centred statement and the
   channel row, then lays the workspace out on a plane tilted away from the
   reader, closing on a strip of what each side of the system does. */
#v-ent #en-approach{position:relative;z-index:2;overflow:hidden;
  background:linear-gradient(180deg,
    #000000 0px,#3b66d6 150px,#E8EDFF 330px,#F4F1E8 520px,#F4F1E8 100%)}
#v-ent #en-approach .top{max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;
  padding:clamp(200px,20vw,330px) var(--pad-x) 0;text-align:center}
#v-ent #en-approach h2{color:var(--ink);font-size:clamp(32px,4.4vw,66px);line-height:1.08;
  letter-spacing:-.02em;font-weight:400;margin:0 auto 24px;max-width:23ch;text-wrap:balance}
#v-ent #en-approach .lede{color:var(--graphite);margin:0 auto;max-width:62ch;text-align:center;
  text-wrap:balance}
#v-ent .chrow{display:flex;flex-wrap:wrap;justify-content:center;gap:clamp(18px,2.6vw,44px);
  max-width:960px;margin:clamp(40px,4.6vw,66px) auto 0}
#v-ent .chrow figure{margin:0;width:64px;text-align:center}
#v-ent .chrow svg{width:26px;height:26px;color:var(--ink)}
#v-ent .chrow figcaption{margin-top:9px;font-size:var(--t-label);color:var(--graphite)}

/* the workspace, laid on a plane tilted away from the reader */
#v-ent .wsstage{margin-top:clamp(44px,5vw,80px);perspective:1500px;perspective-origin:50% 0%;
  height:clamp(420px,42vw,620px)}
#v-ent .wsplane{position:absolute;left:50%;width:min(1560px,124vw);margin-left:min(-700px,-55vw);
  transform:rotateX(49deg) rotateZ(-11deg);transform-style:preserve-3d;
  display:grid;grid-template-columns:210px 250px minmax(0,1fr) 250px;gap:14px;
  padding:0 clamp(16px,2vw,32px)}
#v-ent .ws{background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:14px;
  box-shadow:0 40px 90px rgba(16,20,24,.16);padding:18px;
  font-family:var(--font);
  color:#101418}
#v-ent .ws h4{font-size:13px;font-weight:400;color:#101418;margin-bottom:14px}
/* #8A9199 is 3.19:1 on white */
#v-ent .ws .grp{font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:#6A7178;
  margin:14px 0 7px}
#v-ent .ws .it{display:flex;align-items:center;gap:9px;font-size:12.5px;color:#2A3038;padding:7px 0}
#v-ent .ws .it svg{width:14px;height:14px;color:var(--deep);flex:0 0 auto}
#v-ent .ws .it.on{background:#EFF4FF;border-radius:7px;padding:7px 9px;margin:0 -9px;color:var(--deep)}
#v-ent .ws .doc{font-size:12px;line-height:1.75;color:#3A424C}
#v-ent .ws .doc b{font-weight:400;color:#101418}
#v-ent .ws .doc .hl{background:#EFF4FF;border-radius:3px;padding:1px 4px;color:var(--deep)}
#v-ent .ws .tag{display:inline-block;font-size:10px;letter-spacing:.05em;text-transform:uppercase;
  background:#EFF4FF;color:var(--deep);border:1px solid rgba(49,92,255,.22);
  border-radius:4px;padding:2px 7px;margin-left:auto}

@media(max-width:1000px){
  #v-ent .wsstage{perspective:none;height:auto}
  #v-ent .wsplane{position:static;width:auto;margin:0;transform:none;grid-template-columns:1fr;
    padding:0 var(--pad-x)}
}

/* ===== 3 · THE APPROACH — detail layer =========================
   The workspace is a product screenshot, so its interior uses real product
   colour and real interface type. Third-party marks carry their own brand
   colour (a mark in the wrong colour is a misidentification, not a theme);
   every piece of Truffl's own UI inside the panels stays on the locked
   palette — Deep Cobalt #3b66d6 for live state, #EFF4FF for its tint.
   Appended deliberately: do not splice this into the rules above. */

#v-ent .chrow{gap:clamp(14px,2.1vw,34px);max-width:1020px}
#v-ent .chrow figure{width:74px}
#v-ent .chrow svg{width:27px;height:27px;margin-inline:auto}
#v-ent .chrow figcaption{white-space:nowrap}
#v-ent .chrow figure.soon svg{color:#9AA1A9}
#v-ent .chrow figure.soon figcaption{color:#6B6B6B}

/* ---- the plane ---- */
#v-ent .wsstage{height:clamp(460px,46vw,700px);
  margin-bottom:clamp(110px,11vw,170px)}
#v-ent .wsplane{grid-template-columns:224px 278px minmax(0,1fr) 272px;gap:16px;
  width:min(1460px,115vw);margin-left:max(-730px,-57.5vw)}
#v-ent .ws{padding:13px 14px;position:relative;display:flex;flex-direction:column}

/* panel chrome: title bar, overflow menu, add affordance */
#v-ent .ws .hd{display:flex;align-items:center;gap:8px;margin-bottom:11px}
#v-ent .ws .hd h4{margin:0;flex:1 1 auto;font-size:13.5px;line-height:1.2}
#v-ent .ws .ctl{width:19px;height:19px;border-radius:5px;border:1px solid rgba(21,21,21,.12);
  display:flex;align-items:center;justify-content:center;color:#6A7178;flex:0 0 auto}
#v-ent .ws .ctl svg{width:11px;height:11px}
#v-ent .ws .ctl.k{width:auto;padding:0 6px;font-size:9.5px;letter-spacing:.02em}

/* workspace identity + search */
#v-ent .ws .wsid{display:flex;align-items:center;gap:8px;padding-bottom:11px;
  border-bottom:1px solid rgba(21,21,21,.08);margin-bottom:11px}
#v-ent .ws .wsid .sq{width:22px;height:22px;border-radius:6px;background:var(--deep);color:#fff;
  font-size:11px;display:flex;align-items:center;justify-content:center;flex:0 0 auto}
#v-ent .ws .wsid b{font-weight:400;font-size:12.5px;color:#101418;flex:1 1 auto;
