#v-ent #en-agents .lede{color:var(--graphite);font-size:var(--t-lead);line-height:1.55;
  margin:0 auto clamp(38px,4.4vw,58px);max-width:56ch;text-wrap:balance}
/* the same glow as the closing block, inverted for a light ground */
#v-ent .btn-glow.on-light{background:var(--ink);color:var(--paper)}
