#v-ent .tcard p{font-size:var(--t-small);line-height:1.62;color:var(--graphite)}
#v-ent .tcard .acts{display:flex;flex-wrap:wrap;gap:7px;margin-top:18px;
  padding-top:16px;border-top:1px solid rgba(21,21,21,.10)}
