/* ---------- appended last, so nothing upstream can swallow it ----------
   NB: a previous edit here used a lookahead that ran past this block and
   deleted the two-column silos rule. Keep additions at the very end. */

/* the loop sits left, the caller photograph takes the space on the right */
#v-ent .silos{aspect-ratio:auto;display:grid;
  grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);
  gap:clamp(20px,3vw,52px);align-items:center;max-width:1160px}
#v-ent .loopwrap{position:relative;aspect-ratio:620/470;min-height:330px}
#v-ent .silos .silo{width:clamp(140px,13vw,178px);padding:12px 14px}
#v-ent .silos .agent{width:clamp(118px,11vw,150px)}
#v-ent .caller{border:1px solid rgba(21,21,21,.14);border-radius:6px;background:var(--paper);
  padding:clamp(16px,2vw,24px) clamp(16px,2vw,24px) clamp(12px,1.4vw,16px);margin:0}
#v-ent .caller img{display:block;width:100%;height:auto;border-radius:4px;
  aspect-ratio:4/3;object-fit:cover;object-position:50% 34%}
#v-ent .caller figcaption{margin-top:clamp(10px,1.4vw,16px);text-align:center;
  font-size:var(--t-small);line-height:1.5;color:var(--graphite)}
@media(max-width:900px){
  #v-ent .silos{grid-template-columns:1fr;gap:22px}
  #v-ent .loopwrap{aspect-ratio:auto;min-height:0}
  #v-ent .caller{order:-1}
}

/* the journey reads as one surface, not a framed box, and the checkout
   fills its column so it squares off against the three rows beside it.
   Cropping right-of-centre keeps Payment Method and Order Summary -- the
   part the caption is actually about -- and loses the address form. */
#v-ent #rr-thesis .journey{border:0;border-radius:0;column-gap:clamp(18px,2.2vw,36px)}
#v-ent #rr-thesis .journey > .cartshot{padding:0;border-right:0;background:transparent;
  display:flex;flex-direction:column;justify-content:flex-start;min-height:0}
#v-ent #rr-thesis .journey > .cartshot img{border:0;flex:1 1 auto;min-height:0;
  width:100%;height:100%;object-fit:cover;object-position:100% 50%;border-radius:6px}
#v-ent #rr-thesis .journey > .cartshot figcaption{flex:0 0 auto;margin-top:clamp(12px,1.5vw,18px)}

/* deployment: no frame, and it uses the width the rest of the page uses.
   The photograph fills its column edge to edge rather than floating in a
   padded card, and the four stages sit two-up beside it. */
#v-ent .depwrap{display:grid;grid-template-columns:minmax(0,.46fr) minmax(0,.54fr);
  gap:clamp(20px,2.6vw,44px);align-items:stretch;
  margin:clamp(46px,5vw,74px) auto 0;max-width:none;width:100%;
  background:transparent;border:0;border-radius:0;overflow:visible}
#v-ent .devshot{margin:0;padding:0;border:0;background:transparent;
  display:flex;flex-direction:column;min-height:0}
#v-ent .devshot img{display:block;width:100%;flex:1 1 auto;min-height:280px;
  object-fit:cover;object-position:38% 50%;border-radius:6px}
#v-ent .devshot figcaption{flex:0 0 auto;margin-top:clamp(12px,1.5vw,18px);text-align:center;
  font-size:var(--t-small);line-height:1.5;color:var(--graphite)}
#v-ent .depwrap .stages{margin:0;max-width:none;border:0;border-radius:0;
  grid-template-columns:repeat(2,minmax(0,1fr));align-self:stretch}
#v-ent .depwrap .stages > li{padding:clamp(20px,2.2vw,30px) clamp(18px,2vw,28px);
  border-right:1px solid rgba(21,21,21,.12);
  border-bottom:1px solid rgba(21,21,21,.12)}
#v-ent .depwrap .stages > li:nth-child(2n){border-right:0}
#v-ent .depwrap .stages > li:nth-last-child(-n+2){border-bottom:0}

@media(max-width:900px){
  #v-ent .depwrap{grid-template-columns:1fr;gap:24px}
  #v-ent .devshot img{min-height:220px}
  #v-ent .depwrap .stages{grid-template-columns:1fr}
  #v-ent .depwrap .stages > li{border-right:0;border-bottom:1px solid rgba(21,21,21,.12)}
  #v-ent .depwrap .stages > li:last-child{border-bottom:0}
}

/* ================= merged shell: two views in one document =================
   Both pages ship the same design system, so :root and the resets are kept
   once. Everything page-specific is scoped under its view, and the RR view's
   two shared ids (#pagebg, #foot) were renamed so getElementById cannot pick
   up the home view's copies. */
.view{display:none;position:relative}
.view.on{display:block}

/* Solutions menu — lives in both headers, both of which sit on a dark ground */
/* The header and the hero are siblings, both position:relative z-index:2, so
   the hero wins on DOM order and paints over the header. The dropdown's own
   z-index cannot escape the header's stacking context, so the menu was visible
   but the hero owned hit-testing: clicks landed on the headline, not the link.
   Lift the whole header above the hero. */
#v-home .site-head,#v-rr .site-head{z-index:70}
.navsol{position:relative;display:inline-block}
.navsol-t{font:inherit;font-size:var(--t-small);line-height:inherit;color:inherit;
  background:none;border:0;padding:0;cursor:pointer;display:inline-flex;align-items:center;gap:7px}
.navsol-t::after{content:'';width:5px;height:5px;flex:0 0 auto;
  border-right:1.4px solid currentColor;border-bottom:1.4px solid currentColor;
  transform:rotate(45deg) translateY(-2px);opacity:.75;transition:transform .2s}
.navsol.open .navsol-t::after{transform:rotate(225deg) translateY(-2px)}
.navsol-m{position:absolute;top:calc(100% + 16px);left:-16px;min-width:302px;z-index:80;
  background:rgba(8,8,10,.97);border:1px solid rgba(244,241,232,.16);border-radius:6px;
  padding:8px;display:none;text-align:left}
.navsol.open .navsol-m{display:block}
.navsol-m a{display:block;padding:11px 12px;border-radius:4px}
.navsol-m a b{display:block;font-weight:400;font-size:var(--t-body);color:var(--paper)}
.navsol-m a i{display:block;font-style:normal;font-size:var(--t-small);line-height:1.45;
  color:rgba(244,241,232,.62);margin-top:3px}
.navsol-m a:hover,.navsol-m a:focus-visible{background:rgba(244,241,232,.09)}

/* ============ home view: the Cart recovery ground ============
   The landing page now runs the same field as the Cart recovery page --
   a black-to-cobalt-to-Paper hero, one dark feature section, then light
   all the way to a Paper footer. The canvas light-fields that painted the
   old dark page are retired; the ground is pure CSS, as it is over there. */
/* Cart recovery still inherits Paper -- its hero and orb sections rely on it.
   The document body is Ink now for the light home view, so state it here. */
#v-rr{color:var(--paper)}
#v-home{color:var(--ink)}
#v-home #pagebg,#v-home #burst,#v-home #closebg,#v-home #k1bg{display:none!important}
#v-home{background:var(--paper)}

/* The landing reference uses a muted field of vertical colour blocks.
   The dark wash keeps the headline readable; the lower fade joins the next section. */
#v-home #stage{color:var(--paper);
  background-image:
    linear-gradient(180deg, transparent 80%, rgba(244,241,232,.12) 85%,
      rgba(244,241,232,.76) 95%, #F4F1E8 100%),
    linear-gradient(rgba(11,13,19,.59),rgba(11,13,19,.59)),
    var(--hero-pattern);
  background-color:#474b52;background-size:100% 100%;background-position:center;
  background-repeat:no-repeat}
#v-home #stage .hero h1{color:var(--paper)}
/* Jet worked while the ground was Signal Cobalt; on a photograph it would
   disappear. Pale Cobalt keeps the accent and clears AA on any dark scrim. */
#v-home #stage .hero h1 em{color:var(--pale);font-style:normal}
/* Paper at 88% on Signal Cobalt is 3.86:1; at full strength it is 4.53 */
#v-home #stage .thesis{color:var(--paper)}
#v-home #stage .btn-solid{background:var(--paper);color:var(--jet)}
#v-home #stage .btn-ghost{border-color:rgba(244,241,232,.5);color:var(--paper);
  background:rgba(11,13,19,.55);backdrop-filter:blur(3px)}
#v-home #stage .site-head .actions .talk{color:rgba(244,241,232,.82)}
#v-home #stage .site-head .actions .login{background:var(--paper);color:var(--jet)}
#v-home #stage .card{background:rgba(11,13,19,.82);border:1px solid rgba(244,241,232,.28);
  backdrop-filter:blur(6px);box-shadow:0 26px 60px rgba(0,0,0,.45)}
#v-home #stage .chip{border:1px solid rgba(244,241,232,.32);color:var(--paper)}
#v-home #stage .chip[aria-pressed="true"]{background:var(--paper);color:var(--jet);
  border-color:var(--paper)}
#v-home #stage .card .agent{color:rgba(244,241,232,.72);border:1px solid rgba(244,241,232,.22)}
#v-home #stage .card .agent i{color:rgba(244,241,232,.5)}
#v-home #stage .card .play{border:1px solid rgba(244,241,232,.5);color:var(--paper)}

/* works: the one dark feature moment, welded on both sides. Its four
   illustrations are painted into canvas in Paper, so this section stays dark
   -- the same role the conversation-intelligence panel plays on Cart recovery. */
#v-home #works{color:var(--paper);
  background:linear-gradient(180deg,
    #F4F1E8 0px, #E8EDFF 55px, #3b66d6 145px, #000000 250px,
    #000000 calc(100% - 250px), #3b66d6 calc(100% - 145px),
    #E8EDFF calc(100% - 55px), #F4F1E8 100%)}
/* the copy has to clear the descent, or Paper text lands on the pale ground */
#v-home #works .head{padding-top:clamp(180px,16vw,290px)}
#v-home #works .panels{padding-bottom:clamp(180px,16vw,290px)}
#v-home #works .bx{background:rgba(0,0,0,.46);border:1px solid rgba(244,241,232,.16);
  border-top-color:rgba(244,241,232,.30);box-shadow:0 18px 42px rgba(0,0,0,.5)}
#v-home #works .bx.on{background:rgba(0,0,0,.64);
  box-shadow:0 22px 48px rgba(0,0,0,.62),inset 0 1px 0 rgba(244,241,232,.14)}
#v-home #works .bx p{color:rgba(244,241,232,.6)}

/* the sticky stack: three light panels, each opaque so they can pin over
   one another, stepping Paper -> Pale Cobalt as you scroll through them */
#v-home #stack{background:#F4F1E8}
#v-home .scard{background-image:none!important}
#v-home #k0c{background-color:#F4F1E8}
#v-home #k2c{background-color:#E8EDFF;background-image:none!important}

/* and light the rest of the way out */
/* the stack's last card ends on Pale Cobalt, so Connect has to carry the
   hand-off rather than meet it as a step */
#v-home #connect{background:linear-gradient(180deg,#E8EDFF 0%,#F4F1E8 46%,#F4F1E8 100%)}
#v-home #faq{background:linear-gradient(180deg,#F4F1E8 0%,#E8EDFF 48%,#F4F1E8 100%)}
#v-home #close{background:#F4F1E8}
#v-home #foot{background:var(--paper)}
/* the inverted label alpha lands at 3.36 on Paper; Graphite is the light-ground value */
#v-home #foot .ft-cols p{color:var(--graphite)}

.ft-sub{padding-left:14px;position:relative}
.ft-sub::before{content:'';position:absolute;left:2px;top:.72em;width:6px;height:1px;
  background:currentColor;opacity:.4}

/* ==========================================================================
   ENTERPRISE — ONE LIGHT GROUND
   The page opened on Jet and resolved to Paper halfway down, so it read as two
   pages stitched together. Everything is now on the Paper ground the approach,
   actions, presets and closing sections already use; Signal and Deep Cobalt do
   the accenting they do everywhere else.

   Written as one appended override rather than edits in place: same
   specificity, later source order, so deleting this block restores the dark
   page exactly. Text colours only where a colour changes meaning — surface and
   border alphas are set independently and must not be lifted together.
   ========================================================================== */

/* ---- grounds ---- */
#v-ent #en-hero{color:var(--ink);background:
  linear-gradient(180deg, rgba(244,241,232,0) 74%, rgba(244,241,232,.62) 90%, #F4F1E8 100%),
  radial-gradient(120% 60% at 50% 94%, rgba(49,92,255,.22) 0%, rgba(24,56,168,.09) 40%, rgba(0,0,0,0) 72%),
  radial-gradient(80% 50% at 50% -10%, rgba(49,92,255,.10) 0%, rgba(0,0,0,0) 70%),
  #F4F1E8}
/* the scrim still separates the copy from the moving field, in Paper now */
#v-ent #en-hero .scrim{background:
  radial-gradient(58% 44% at 50% 58%, rgba(244,241,232,.90) 0%, rgba(244,241,232,.70) 46%, rgba(244,241,232,.18) 80%, rgba(244,241,232,0) 100%),
  linear-gradient(180deg, rgba(244,241,232,.55) 0%, rgba(244,241,232,0) 26%, rgba(244,241,232,0) 62%, rgba(244,241,232,.55) 100%)}
#v-ent #en-vigs{background:
  radial-gradient(74% 38% at 8% 30%, rgba(49,92,255,.11) 0%, rgba(0,0,0,0) 64%),
  radial-gradient(60% 32% at 92% 66%, rgba(24,56,168,.09) 0%, rgba(0,0,0,0) 62%),
  linear-gradient(180deg,#F4F1E8 0%,#F4F1E8 8%,#F7F5EF 34%,#F7F5EF 62%,#F4F1E8 100%)}
/* the approach section opened on Jet to meet the old dark grid; it now opens
   on the Paper the grid hands it, with the cobalt kept as a wash */
#v-ent #en-approach{background:linear-gradient(180deg,
  #F4F1E8 0px,#E8EDFF 130px,#E8EDFF 300px,#F4F1E8 520px,#F4F1E8 100%)}
#v-ent #en-approach .top{padding-top:clamp(104px,10.5vw,168px)}

/* ---- header and hero copy ---- */
#v-ent .site-head .actions .talk{color:rgba(21,21,21,.8)}
#v-ent .site-head .actions .login{background:var(--ink);color:var(--paper)}
#v-ent #en-hero h1{color:var(--ink)}
#v-ent #en-hero .sub{color:rgba(21,21,21,.78)}
#v-ent #en-hero .kick,#v-ent .kick{color:var(--graphite)}
#v-ent .sec .lede{color:var(--graphite)}
#v-ent .sec .close-line{color:var(--graphite)}

/* ---- buttons ---- */
#v-ent .btn-solid{background:var(--ink);color:var(--paper)}
#v-ent .btn-ghost{border-color:rgba(21,21,21,.28);color:var(--ink)}
#v-ent .btn-glow,#v-ent #en-cta .btn-glow{
  background:var(--signal);color:#fff;border:1px solid var(--signal);
  box-shadow:0 6px 18px rgba(49,92,255,.16);
  transition:background .2s,border-color .2s,box-shadow .2s}
#v-ent .btn-glow::before{display:none;animation:none}
#v-ent .btn-glow:hover,#v-ent #en-cta .btn-glow:hover{
  background:var(--deep);border-color:var(--deep);box-shadow:0 8px 22px rgba(49,92,255,.22)}
#v-ent .btn-glow:focus-visible{outline:2px solid var(--signal);outline-offset:4px}
#v-ent .btn-line{color:var(--ink);border-color:rgba(21,21,21,.3)}

/* ---- the falling scene ---- */
#v-ent .hb-lane::before{background:linear-gradient(180deg,rgba(21,21,21,0),rgba(21,21,21,.12),rgba(21,21,21,0))}
#v-ent .hb-item{background:#fff;border:1px solid rgba(21,21,21,.10);
  box-shadow:0 26px 60px rgba(16,20,24,.16)}
#v-ent .hb-item svg{color:var(--ink);opacity:1}
/* a mark in the wrong colour is a misidentification, so the tiles carry the
   vendors' own, as the sections below already do */
#v-ent .hb-item svg[aria-label="Gmail"]{color:#EA4335}
#v-ent .hb-item svg[aria-label="WhatsApp"]{color:#25D366}
#v-ent .hb-item svg[aria-label="Slack"]{color:#4A154B}
#v-ent .hb-item svg[aria-label="Shopify"]{color:#7AB55C}
#v-ent .hb-item svg[aria-label="Salesforce"]{color:#00A1E0}
#v-ent .hb-item svg[aria-label="HubSpot"]{color:#FF7A59}
#v-ent .hb-item svg[aria-label="Zendesk"]{color:#03363D}
#v-ent .hb-item svg[aria-label="Stripe"]{color:#635BFF}
#v-ent .hb-item svg[aria-label="Twilio"]{color:#F22F46}
#v-ent .hb-item svg[aria-label="Intercom"]{color:#1F8DED}
#v-ent .hb-item svg[aria-label="Notion"]{color:#151515}
#v-ent .hb-item svg[aria-label="Calendar"]{color:#1A73E8}

#v-ent .hb-p{background:#fff;border:1px solid rgba(21,21,21,.10);
  box-shadow:0 34px 76px rgba(16,20,24,.18);color:#101418}
#v-ent .hb-p .hd{border-bottom:1px solid rgba(21,21,21,.08);background:#FAFAF7;color:#565C63}
#v-ent .hb-p .hd .r{color:var(--deep)}
#v-ent .hb-p .ln{border-top:1px solid rgba(21,21,21,.07)}
#v-ent .hb-p .ln:first-child{border-top:0}
#v-ent .hb-p .ln .k{color:#565C63}
#v-ent .hb-p .ln .v{color:#101418}
#v-ent .hb-p .ln .t{color:#5F666D}
#v-ent .hb-p .av{background:var(--deep);color:#fff}
#v-ent .hb-p .quote{color:#101418}
#v-ent .hb-p .sub{color:#565C63}
#v-ent .hb-p .pill{background:#EFF4FF;color:var(--deep);border:1px solid rgba(49,92,255,.24)}
#v-ent .hb-p .nav{color:#3A424C}
#v-ent .hb-p .nav b{color:#101418}
#v-ent .hb-p .nav i{color:#5F666D}

/* ---- feature grid ---- */
#v-ent .fh{color:var(--graphite)}
#v-ent .fh b{color:var(--ink)}
#v-ent .m{background:#fff;border:1px solid rgba(21,21,21,.10);
  box-shadow:0 28px 64px rgba(16,20,24,.14);color:#101418}
#v-ent .m-hd{border-bottom:1px solid rgba(21,21,21,.08)}
/* Paper on Signal is 4.53 and this is 11px, so the avatar sits on Deep */
#v-ent .m-hd .av{background:var(--deep);color:#fff}
#v-ent .m-hd .close{border:1px solid rgba(21,21,21,.18);color:#3A424C}
#v-ent .m-row{color:#101418}
#v-ent .m-row .tm{color:#565C63}
#v-ent .m-foot{color:#565C63}
#v-ent .m-foot .live{color:var(--deep)}
#v-ent .m-pill{border:1px solid rgba(21,21,21,.2);color:#101418;background:#fff}
#v-ent .m-pill span{background:var(--deep);border:1px solid var(--signal);color:#fff}
#v-ent .m-list .r{border-top:1px solid rgba(21,21,21,.08)}
#v-ent .m-list .r:first-child{border-top:0}
#v-ent .m-list .r .av{background:var(--deep);color:#fff}
#v-ent .m-list .r b{color:#101418}
#v-ent .m-list .r i{color:#565C63}
#v-ent .m-list .r .tm{color:#565C63}
#v-ent .m-sub{color:#565C63;border-bottom:1px solid rgba(21,21,21,.08)}
#v-ent .msg{background:#fff;border:1px solid rgba(21,21,21,.10);
  box-shadow:0 20px 48px rgba(16,20,24,.12)}
#v-ent .msg:nth-child(1){opacity:.88}
#v-ent .msg .ch{color:#565C63}
#v-ent .msg .ch svg{color:#3A424C}
#v-ent .msg p{color:#101418}
#v-ent .m-fields .f{border-top:1px solid rgba(21,21,21,.08)}
#v-ent .m-fields .f:first-child{border-top:0}
#v-ent .m-fields .f span{color:#565C63}
#v-ent .m-fields .f b{color:#101418}
#v-ent .langmenu{background:#fff;border:1px solid rgba(21,21,21,.14);
  box-shadow:0 24px 60px rgba(16,20,24,.20)}
#v-ent .langmenu .s{color:#565C63}
#v-ent .langmenu .o{color:#2A3038}
#v-ent .langmenu .o em{color:#5F666D}
#v-ent .langmenu .o.on{background:var(--deep);color:#fff}
#v-ent .langmenu .o.on em{color:var(--pale)}

/* ---- the closing block of the grid ---- */
/* Both blooms were centred at or below the block's bottom edge, so the wash
   was at full strength on the last row -- fine when the next section opened on
   Jet, a 42-level step now that it opens on Paper. The blooms sit inside the
   block, and a Paper veil resolves the last rows to exactly the ground the
   approach section starts on. */
#v-ent .fwide{background:
  linear-gradient(180deg, rgba(244,241,232,0) 58%, rgba(244,241,232,.72) 86%, #F4F1E8 100%),
  radial-gradient(90% 70% at 26% 84%, rgba(49,92,255,.30) 0%, rgba(24,56,168,.12) 42%, rgba(0,0,0,0) 74%),
  radial-gradient(62% 54% at 84% 72%, rgba(24,56,168,.17) 0%, rgba(0,0,0,0) 66%)}
#v-ent .cardstack .c{background:#fff;border:1px solid rgba(21,21,21,.10);
  box-shadow:0 40px 92px rgba(16,20,24,.20)}
#v-ent .cardstack .f{border-top:1px solid rgba(21,21,21,.08)}
#v-ent .cardstack .f:first-child{border-top:0}
#v-ent .cardstack .f span{color:#565C63}
#v-ent .cardstack .f b{color:#101418}
#v-ent .cardstack .appr{color:#565C63}
#v-ent .cardstack .appr i{background:var(--deep);color:#fff}
#v-ent .cardstack .act{border-top:1px solid rgba(21,21,21,.1);color:#101418}
#v-ent .cardstack .act svg{color:var(--deep)}
#v-ent .cardstack .go{background:#fff;border:1px solid rgba(21,21,21,.2);color:#101418}
#v-ent .cardstack .pill{background:#fff;border:1px solid rgba(21,21,21,.2);color:#101418}

/* the wordmark's Paper group is a presentation attribute on the <g>; any CSS
   rule outranks one, so the header mark flips to Ink without touching markup.
   The cobalt "ff" is already correct on either ground. */
#v-ent .site-head .mark svg g[fill="#F4F1E8"]{fill:var(--ink)}

/* ---- the header has to outrank the page it sits on ----
   The Solutions menu is a child of .site-head, so its own z-index:80 is
   trapped in the header's stacking context and cannot lift it past a sibling
   that outranks the header. The hero content is z-index 3 on Enterprise, and
   z-index 2 but later in DOM order on the landing page, so in both cases
   hit-testing handed the click to the hero: the menu opened, looked live, and
   did nothing. Raising the header itself is the fix -- the menu never needed
   its own. Verified by elementFromPoint on every nav target, not by a
   synthetic click, which bypasses hit-testing and reports success either way. */
#v-home .site-head,#v-rr .site-head,#v-ent .site-head{z-index:70}

/* ==========================================================================
   SOLUTIONS · RETAIL CUSTOMER SUPPORT  (#v-cx)
   Fashion and lifestyle retail with physical stores. One light Paper ground
   throughout, as on Enterprise; Signal and Deep Cobalt carry state.
   No headset, call-centre photograph, microphone or decorative waveform —
   the hero is the customer's question with the business context assembling
   around it. No resolution, containment, CSAT or queue figures anywhere:
   the operations section shows the categories only, and the interactive
   flow is labelled as illustrative.
   ========================================================================== */

#v-cx{background:#fff;color:var(--ink)}
#v-cx .site-head{position:relative;z-index:70;height:66px;flex:0 0 auto}
#v-cx .site-head .mark{position:absolute;left:var(--pad-x);top:50%;transform:translateY(-50%);line-height:0}
#v-cx .site-head .mark svg{display:block;margin:0}
#v-cx .site-head .mark svg g[fill="#F4F1E8"]{fill:var(--ink)}
#v-cx .site-head nav{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  display:flex;gap:30px;font-size:var(--t-small);white-space:nowrap}
#v-cx .site-head .actions{position:absolute;right:var(--pad-x);top:50%;transform:translateY(-50%);
  display:flex;gap:8px;align-items:center}
#v-cx .site-head .actions .talk{color:rgba(21,21,21,.8);font-size:var(--t-small)}
#v-cx .site-head .actions .login{background:var(--ink);color:var(--paper);font-size:var(--t-label);
  font-weight:700;letter-spacing:.08em;text-transform:uppercase;padding:9px 16px;border-radius:2px}
@media(max-width:700px){ #v-cx .site-head nav{display:none} }

#v-cx .sec{position:relative;z-index:2}
#v-cx .wrapc{max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;padding:0 var(--pad-x)}
#v-cx .kick{font-size:var(--t-label);letter-spacing:.14em;text-transform:uppercase;color:var(--graphite)}
#v-cx .lede{font-size:var(--t-lead);line-height:1.6;color:var(--graphite);max-width:62ch}
#v-cx .close-line{font-size:var(--t-body);line-height:1.6;color:var(--graphite);
  border-left:2px solid var(--signal);padding-left:15px;max-width:66ch;margin-top:clamp(30px,3.4vw,46px)}
/* Keep page heading typography out of the shared footer. */
#v-cx h2:not(:where(.global-footer h2)){font-size:clamp(30px,3.9vw,58px);line-height:1.08;letter-spacing:-.02em;
  font-weight:400;color:var(--ink);margin:14px 0 18px;max-width:20ch;text-wrap:balance}

/* ---- buttons ---- */
#v-cx .btn-glow{position:relative;display:inline-flex;align-items:center;gap:9px;z-index:1;
  font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;font-weight:700;
  padding:15px 30px;border-radius:2px;background:var(--ink);color:var(--paper)}
#v-cx .btn-glow::before{content:"";position:absolute;inset:-24px;border-radius:14px;z-index:-1;
  background:radial-gradient(closest-side, rgba(49,92,255,.92), rgba(24,56,168,.42) 52%, rgba(0,0,0,0) 78%);
  filter:blur(18px);animation:glowPulse 3.6s ease-in-out infinite}
#v-cx .btn-line{font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  color:var(--ink);border:1px solid rgba(21,21,21,.3);border-radius:2px;padding:15px 26px}
#v-cx .ctas{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;align-items:center}

/* ===================== 1 · HERO ===================== */
#v-cx #cx-hero{overflow:hidden;background:
  radial-gradient(96% 56% at 50% 8%, rgba(49,92,255,.13) 0%, rgba(0,0,0,0) 68%),
  linear-gradient(180deg,#F4F1E8 0%,#F4F1E8 62%,#F4F1E8 100%)}
#v-cx #cx-hero .in{max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;
  padding:clamp(46px,5.2vw,76px) var(--pad-x) clamp(66px,7.4vw,110px);text-align:center}
#v-cx #cx-hero h1{font-size:clamp(32px,4.4vw,66px);line-height:1.06;letter-spacing:-.024em;
  font-weight:400;color:var(--ink);margin:18px auto 24px;max-width:19ch;text-wrap:balance}
#v-cx #cx-hero .sub{font-size:var(--t-lead);line-height:1.58;color:var(--graphite);
  max-width:66ch;margin:0 auto 18px;text-wrap:balance}
#v-cx #cx-hero .askline{font-size:var(--t-body);color:rgba(21,21,21,.7);margin:0 auto 36px}
#v-cx #cx-hero .askline em{font-style:normal;color:var(--ink)}

/* the scene: one spoken question, with the business context assembling round it */
#v-cx .scene{position:relative;margin:clamp(36px,4.2vw,60px) auto 0;max-width:1060px;
  min-height:clamp(296px,27vw,356px)}
#v-cx .said{position:relative;z-index:3;margin-inline:auto;max-width:min(520px,86%);
  background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:12px;
  box-shadow:0 26px 62px rgba(16,20,24,.14);padding:18px 20px;text-align:left}
#v-cx .said .who{display:flex;align-items:center;gap:9px;font-size:var(--t-label);
  letter-spacing:.08em;text-transform:uppercase;color:var(--graphite);margin-bottom:11px}
#v-cx .said .who i{width:7px;height:7px;border-radius:50%;background:var(--signal);
  display:block;flex:0 0 auto;font-style:normal}
#v-cx .said p{font-size:var(--t-lead);line-height:1.45;color:var(--ink)}
#v-cx .ctxs{position:absolute;inset:0;z-index:2;pointer-events:none}
#v-cx .ctx{position:absolute;background:#fff;border:1px solid rgba(21,21,21,.10);
  border-radius:10px;box-shadow:0 18px 44px rgba(16,20,24,.11);padding:11px 13px;width:186px;
  opacity:0;transform:translateY(10px);transition:opacity .6s ease,transform .6s ease}
#v-cx .scene.lit .ctx{opacity:1;transform:none}
#v-cx .ctx .lb{font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  color:var(--graphite);margin-bottom:6px;display:flex;align-items:center;gap:7px}
#v-cx .ctx .lb svg{width:13px;height:13px;color:var(--deep);flex:0 0 auto}
#v-cx .ctx b{display:block;font-weight:400;font-size:var(--t-small);color:var(--ink);line-height:1.35}
#v-cx .ctx.quiet{opacity:0;box-shadow:none;background:rgba(255,255,255,.5);border-style:dashed}
#v-cx .scene.lit .ctx.quiet{opacity:.55}
#v-cx .ctx.quiet b{color:var(--graphite)}
#v-cx .c1{left:0;top:13%}  #v-cx .c2{right:0;top:5%}
#v-cx .c3{left:7%;bottom:3%} #v-cx .c4{right:6%;bottom:11%}
#v-cx .c5{left:50%;bottom:0;transform:translateX(-50%) translateY(10px);width:236px}
#v-cx .scene.lit .c5{transform:translateX(-50%)}
#v-cx .scene.lit .c1{transition-delay:.15s} #v-cx .scene.lit .c2{transition-delay:.3s}
#v-cx .scene.lit .c3{transition-delay:.45s} #v-cx .scene.lit .c4{transition-delay:.6s}
#v-cx .scene.lit .c5{transition-delay:.85s}
#v-cx .c5{border-color:var(--signal)}
@media(max-width:860px){
  #v-cx .scene{min-height:0}
  #v-cx .ctxs{position:static;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));
    gap:10px;margin-top:16px}
  #v-cx .ctx{position:static;width:auto;transform:none!important}
}
@media(prefers-reduced-motion:reduce){#v-cx .ctx{transition:none}}

/* ===================== 2 · THESIS ===================== */
#v-cx #cx-thesis{background:linear-gradient(180deg,#F4F1E8 0%,#E8EDFF 46%,#E8EDFF 62%,#F4F1E8 100%);
  padding:clamp(80px,9vw,140px) 0 clamp(18px,2.2vw,30px)}
#v-cx #cx-thesis .head{text-align:center;max-width:78ch;margin-inline:auto}
#v-cx #cx-thesis h2{margin-inline:auto;max-width:22ch}
#v-cx #cx-thesis .lede{margin-inline:auto;text-align:center;max-width:72ch}
#v-cx .qgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(206px,1fr));
  gap:clamp(12px,1.4vw,18px);margin-top:clamp(44px,5vw,72px)}
#v-cx .qcard{background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:6px;
  padding:clamp(18px,2vw,24px);box-shadow:0 16px 38px rgba(16,20,24,.08)}
#v-cx .qcard q{display:block;font-size:var(--t-body);line-height:1.45;color:var(--ink);
  margin-bottom:11px;quotes:'\201C' '\201D'}
#v-cx .qcard p{font-size:var(--t-small);line-height:1.55;color:var(--graphite)}

/* ===================== 3 · INTERACTIVE FLOW ===================== */
#v-cx #cx-flow{background:#fff;padding:clamp(26px,3vw,44px) 0 clamp(84px,9vw,140px)}
#v-cx #cx-flow .head{max-width:62ch}
#v-cx .illus{display:inline-flex;align-items:center;gap:8px;font-size:var(--t-label);
  letter-spacing:.08em;text-transform:uppercase;color:var(--deep);
  background:#EFF4FF;border:1px solid rgba(49,92,255,.24);border-radius:4px;padding:5px 10px}
#v-cx .flowwrap{display:grid;grid-template-columns:minmax(0,.44fr) minmax(0,.56fr);
  gap:clamp(16px,2vw,26px);margin-top:clamp(34px,4vw,56px);align-items:start}
#v-cx .panel{background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:12px;
  box-shadow:0 22px 54px rgba(16,20,24,.10);overflow:hidden}
#v-cx .panel .ph{display:flex;align-items:center;gap:9px;padding:14px 17px;font-size:var(--t-small);
  color:var(--ink);border-bottom:1px solid rgba(21,21,21,.08)}
#v-cx .panel .ph i{width:7px;height:7px;border-radius:50%;background:var(--signal);
  font-style:normal;flex:0 0 auto}
#v-cx .panel .pb{padding:16px 17px}
#v-cx .rec dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:9px 16px}
#v-cx .rec dt{font-size:var(--t-small);color:var(--graphite);white-space:nowrap}
#v-cx .rec dd{font-size:var(--t-small);color:var(--ink)}
#v-cx .turn{padding:15px 17px;border-top:1px solid rgba(21,21,21,.08)}
#v-cx .turn .sp{font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  color:var(--graphite);margin-bottom:8px}
#v-cx .turn p{font-size:var(--t-body);line-height:1.55;color:var(--ink)}
#v-cx .turn.agent{background:#FAFAF6}
#v-cx .turn.agent .sp{color:var(--deep)}

/* the ladder */
#v-cx .ladder{list-style:none}
#v-cx .ladder li{display:grid;grid-template-columns:104px minmax(0,1fr);gap:clamp(14px,1.8vw,26px);
  padding:clamp(13px,1.5vw,18px) 0;border-top:1px solid rgba(21,21,21,.10)}
#v-cx .ladder li:first-child{border-top:0;padding-top:0}
#v-cx .ladder .st{font-size:var(--t-label);letter-spacing:.1em;text-transform:uppercase;
  color:var(--deep);padding-top:2px}
#v-cx .ladder p{font-size:var(--t-body);line-height:1.55;color:var(--ink)}
#v-cx .ladder .chk{margin-top:9px;display:flex;flex-wrap:wrap;gap:6px}
#v-cx .ladder .chk span{font-size:var(--t-label);color:var(--graphite);
  border:1px solid rgba(21,21,21,.16);border-radius:4px;padding:4px 8px}
#v-cx .ladder .chk span.hit{border-color:var(--signal);color:var(--deep);background:#EFF4FF}

/* the outcome strip */
#v-cx .outcome{display:flex;flex-wrap:wrap;gap:8px;margin-top:clamp(18px,2vw,26px)}
#v-cx .outcome span{display:inline-flex;align-items:center;gap:8px;font-size:var(--t-small);
  color:var(--ink);background:#fff;border:1px solid rgba(21,21,21,.12);border-radius:4px;padding:8px 12px}
#v-cx .outcome span::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--deep)}
#v-cx .outcome span.warn::before{background:#fff;border:1px solid var(--graphite)}

/* the fact switches */
#v-cx .facts{margin-top:clamp(26px,3vw,42px)}
#v-cx .facts .fl{font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  color:var(--graphite);margin-bottom:12px}
#v-cx .facts .row{display:flex;flex-wrap:wrap;gap:8px}
#v-cx .facts button{font:inherit;font-size:var(--t-small);cursor:pointer;
  background:#fff;border:1px solid rgba(21,21,21,.18);border-radius:4px;padding:10px 14px;
  color:var(--ink);transition:border-color .25s,background .25s}
#v-cx .facts button:hover{border-color:rgba(21,21,21,.4)}
#v-cx .facts button[aria-pressed="true"]{border-color:var(--signal);background:#EFF4FF;color:var(--deep)}
@media(max-width:960px){ #v-cx .flowwrap{grid-template-columns:1fr} }

/* ===================== 4 · COVERAGE ===================== */
#v-cx #cx-cover{background:linear-gradient(180deg,#F4F1E8 0%,#E8EDFF 50%,#F4F1E8 100%);
  padding:clamp(84px,9vw,140px) 0}
#v-cx .cover{display:grid;grid-template-columns:repeat(auto-fit,minmax(288px,1fr));
  gap:clamp(12px,1.4vw,18px);margin-top:clamp(40px,4.6vw,66px)}
#v-cx .ccard{background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:6px;
  padding:clamp(20px,2.3vw,30px);box-shadow:0 16px 40px rgba(16,20,24,.08);
  display:flex;flex-direction:column}
#v-cx .ccard > svg{width:24px;height:24px;color:var(--deep);margin-bottom:clamp(16px,1.8vw,22px)}
#v-cx .ccard h3{font-size:var(--t-label);letter-spacing:.1em;text-transform:uppercase;
  font-weight:400;color:var(--deep);margin-bottom:10px}
#v-cx .ccard p{font-size:var(--t-body);line-height:1.55;color:var(--ink);margin-bottom:14px}
#v-cx .ccard .tags{margin-top:auto;padding-top:14px;border-top:1px solid rgba(21,21,21,.08);
  font-size:var(--t-small);line-height:1.7;color:var(--graphite)}

/* ===================== 5 · HANDOFF ===================== */
#v-cx #cx-hand{background:#F4F1E8;padding:clamp(84px,9vw,140px) 0}
#v-cx .hcols{display:grid;grid-template-columns:repeat(auto-fit,minmax(262px,1fr));
  gap:clamp(14px,1.8vw,24px);margin-top:clamp(40px,4.6vw,66px)}
#v-cx .hcol{background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:6px;
  padding:clamp(20px,2.2vw,28px);box-shadow:0 14px 36px rgba(16,20,24,.07)}
#v-cx .hcol h3{font-size:var(--t-h3);line-height:1.25;font-weight:400;color:var(--ink);
  margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid rgba(21,21,21,.10)}
#v-cx .hcol ul{list-style:none;display:flex;flex-direction:column;gap:11px}
#v-cx .hcol li{display:flex;gap:11px;font-size:var(--t-small);line-height:1.55;color:var(--ink)}
#v-cx .hcol li svg{width:14px;height:14px;color:var(--deep);flex:0 0 auto;margin-top:3px}

/* ===================== 6 · OPERATIONS ===================== */
#v-cx #cx-ops{background:linear-gradient(180deg,#F4F1E8 0%,#E8EDFF 48%,#F4F1E8 100%);
  padding:clamp(84px,9vw,140px) 0}
#v-cx .ops{display:grid;grid-template-columns:repeat(auto-fit,minmax(272px,1fr));
  gap:clamp(12px,1.4vw,18px);margin-top:clamp(40px,4.6vw,66px)}
#v-cx .opcard{background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:6px;
  padding:clamp(20px,2.2vw,28px);box-shadow:0 14px 36px rgba(16,20,24,.07)}
#v-cx .opcard h3{font-size:var(--t-label);letter-spacing:.1em;text-transform:uppercase;
  font-weight:400;color:var(--deep);margin-bottom:15px}
#v-cx .opcard ul{list-style:none;display:flex;flex-direction:column}
#v-cx .opcard li{font-size:var(--t-small);line-height:1.5;color:var(--ink);
  padding:9px 0;border-top:1px solid rgba(21,21,21,.08)}
#v-cx .opcard li:first-child{border-top:0;padding-top:0}
#v-cx .nofig{margin-top:clamp(26px,3vw,40px);font-size:var(--t-small);line-height:1.6;
  color:var(--graphite);border-left:2px solid rgba(21,21,21,.2);padding-left:15px;max-width:72ch}

/* ===================== 7 · CONNECTED AND CONTROLLED ===================== */
#v-cx #cx-conn{background:#F4F1E8;padding:clamp(84px,9vw,140px) 0}
#v-cx .igrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
  gap:0;margin-top:clamp(40px,4.6vw,66px);border:1px solid rgba(21,21,21,.12);border-radius:6px;
  overflow:hidden;background:#fff}
#v-cx .igrid > div{padding:clamp(18px,2vw,26px);border-top:1px solid rgba(21,21,21,.10);
  border-left:1px solid rgba(21,21,21,.10)}
#v-cx .igrid > div svg{width:20px;height:20px;color:var(--deep);display:block;margin-bottom:13px}
#v-cx .igrid h3{font-size:var(--t-body);font-weight:400;color:var(--ink);margin-bottom:7px}
#v-cx .igrid p{font-size:var(--t-small);line-height:1.5;color:var(--graphite)}

/* ===================== 8 · DEPLOYMENT ===================== */
#v-cx #cx-deploy{background:linear-gradient(180deg,#F4F1E8 0%,#E8EDFF 50%,#F4F1E8 100%);
  padding:clamp(84px,9vw,140px) 0}
#v-cx .steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
  gap:clamp(14px,1.8vw,24px);margin-top:clamp(40px,4.6vw,66px)}
#v-cx .step{background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:6px;
  padding:clamp(20px,2.2vw,28px);box-shadow:0 14px 36px rgba(16,20,24,.07)}
#v-cx .step .n{font-size:var(--t-label);letter-spacing:.1em;text-transform:uppercase;
  color:var(--deep);margin-bottom:12px;display:flex;align-items:center;gap:9px}
#v-cx .step .n b{font-weight:400;color:var(--graphite);font-variant-numeric:tabular-nums}
#v-cx .step p{font-size:var(--t-small);line-height:1.6;color:var(--ink)}

/* ===================== 9 · FINAL CTA ===================== */
#v-cx #cx-cta{overflow:hidden;background:
  radial-gradient(78% 52% at 50% 52%, rgba(49,92,255,.16) 0%, rgba(49,92,255,.06) 48%, rgba(0,0,0,0) 76%),
  linear-gradient(180deg,#F4F1E8 0%,#E8EDFF 44%,#E8EDFF 60%,#F4F1E8 100%)}
#v-cx #cx-cta .in{text-align:center;max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;
  padding:clamp(110px,12vw,180px) var(--pad-x) clamp(110px,12vw,180px)}
#v-cx #cx-cta h2{margin:0 auto 22px;max-width:18ch;font-size:clamp(34px,4.6vw,68px)}
#v-cx #cx-cta .lede{margin:0 auto clamp(34px,4vw,48px);max-width:56ch;text-align:center}
#v-cx .fields{margin:clamp(46px,5vw,74px) auto 0;max-width:min(880px,92%);
  border-top:1px solid rgba(21,21,21,.14);padding-top:clamp(22px,2.4vw,32px);text-align:left}
#v-cx .fields p{font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  color:var(--graphite);margin-bottom:14px}
#v-cx .fields ul{list-style:none;display:grid;grid-template-columns:repeat(auto-fit,minmax(232px,1fr));
  gap:9px clamp(18px,2.4vw,40px)}
#v-cx .fields li{font-size:var(--t-small);line-height:1.5;color:var(--ink);
  display:flex;gap:10px}
#v-cx .fields li::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--signal);
  flex:0 0 auto;margin-top:8px}

/* the retail-support footer, same rules as the enterprise one -- these are
   scoped per view, so a cloned <footer> with a new id inherits nothing and
   renders its social marks at the SVG default size. */
#v-cx #cxfoot{position:relative;z-index:2;background:var(--paper)}
#v-cx #cxfoot .ft-wrap{
  max-width:calc(var(--content) + var(--pad-x)*2);margin-inline:auto;
  padding:clamp(56px,7vw,96px) var(--pad-x) clamp(28px,3vw,40px)
}
#v-cx #cxfoot .ft-top{
  display:grid;grid-template-columns:minmax(0,1fr) auto;gap:clamp(32px,6vw,96px);
  align-items:start;padding-bottom:clamp(40px,5vw,72px)
}
#v-cx #cxfoot .ft-mark{display:block;line-height:0}
#v-cx #cxfoot .ft-mark svg{display:block;margin:0;width:clamp(132px,14vw,188px);height:auto}
#v-cx #cxfoot .ft-cols{display:grid;grid-template-columns:repeat(2,minmax(120px,1fr));gap:clamp(32px,5vw,80px)}
#v-cx #cxfoot .ft-cols p{
  font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;
  color:var(--graphite);margin-bottom:16px
}
#v-cx #cxfoot .ft-cols a{
  display:block;font-size:var(--t-small);line-height:1.5;color:var(--ink);
  margin-bottom:11px;transition:color .3s
}
#v-cx #cxfoot .ft-cols a:hover{color:var(--deep)}
#v-cx #cxfoot .ft-bar{
  display:flex;align-items:center;gap:clamp(16px,3vw,40px);flex-wrap:wrap;
  padding-top:clamp(20px,2.4vw,30px);border-top:1px solid rgba(21,21,21,.14)
}
#v-cx #cxfoot .ft-legal{font-size:var(--t-label);color:var(--graphite)}
#v-cx #cxfoot .ft-links{display:flex;gap:clamp(14px,2vw,26px)}
#v-cx #cxfoot .ft-links a{font-size:var(--t-label);color:var(--graphite);transition:color .3s}
#v-cx #cxfoot .ft-links a:hover{color:var(--deep)}
#v-cx #cxfoot .ft-social{display:flex;gap:14px;margin-left:auto}
#v-cx #cxfoot .ft-social a{
  width:18px;height:18px;display:block;color:var(--graphite);transition:color .3s
}
#v-cx #cxfoot .ft-social a:hover{color:var(--deep)}
#v-cx #cxfoot .ft-social svg{width:100%;height:100%;display:block}
@media(max-width:700px){
  #v-cx #cxfoot .ft-top{grid-template-columns:1fr;gap:36px}
  #v-cx #cxfoot .ft-social{margin-left:0}
}

/* ==========================================================================
   CX SUPPORT · HERO  — the reference composition, in Truffl's system.
   Solid Signal Cobalt field running behind the header, copy left, the phone
   right. The reference sets its headline in pale pink on blue; Pale Cobalt on
   Signal is 1.03:1, so every word here is Paper, which is 4.53 — the only
   value in the lock that clears AA on this ground. Nothing on the blue is
   dimmed with alpha for the same reason.
   ========================================================================== */

/* the header is a sibling above the hero, so it carries the field itself */
/* ===================== CX HERO (MATCHING PICTURE 1) ===================== */
#v-cx #cx-hero{
  margin: 18px;
  border-radius: 26px;
  background: #3b66d6 !important;
  background-image: none !important;
  overflow: hidden;
  padding: 24px 28px clamp(48px, 6vw, 76px);
  box-sizing: border-box;
  color: #ffffff;
}
#v-cx #cx-hero::after{display:none !important;}

#v-cx #cx-hero .site-head{
  width: 100%;
  max-width: none;
  position: relative;
  inset: auto;
  margin: 0 0 clamp(24px, 3.5vw, 44px);
  min-height: 76px;
  background: #ffffff;
  color: #153471;
  border-radius: 18px;
  padding: 18px 26px;
  border: 0;
  box-shadow: none;
  transform: none;
  display: flex;
  align-items: center;
  box-sizing: border-box;
}
#v-cx #cx-hero .site-head .mark{position: static; transform: none; width: 98px; flex-shrink: 0;}
#v-cx #cx-hero .site-head .mark svg{width: 98px; height: auto;}
#v-cx #cx-hero .site-head .mark svg g[fill="#F4F1E8"],
#v-cx #cx-hero .site-head .mark svg g[fill="#151515"]{fill: #151515;}
#v-cx #cx-hero .site-head .mark svg g[fill="#3b66d6"]{fill: #3b66d6;}
#v-cx #cx-hero .site-head nav{position: static; transform: none; margin: auto; display: flex; gap: 24px;}
#v-cx #cx-hero .site-head nav>a, #v-cx #cx-hero .site-head .navsol-t{color: #153471; font-size: 14px;}
#v-cx #cx-hero .site-head .actions{position: static; transform: none; display: flex; align-items: center; gap: 14px; margin-left: auto;}
#v-cx #cx-hero .site-head .actions .talk{color: #153471; font-size: 14px;}
#v-cx #cx-hero .site-head .actions .login{background: #3b66d6; color: #ffffff; border-radius: 5px; padding: 13px 20px; font-size: 12px;}

@media(max-width:1100px){
  #v-cx #cx-hero .site-head nav{display:none}
  #v-cx #cx-hero .site-head .mobile-menu-toggle{display:flex;position:static;order:3;margin-left:10px;width:44px;height:44px;transform:none}
}
@media(max-width:760px){
  #v-cx #cx-hero{margin: 12px; padding: 16px 14px 30px; border-radius: 22px;}
  #v-cx #cx-hero .site-head{padding: 14px 15px; gap: 8px; border-radius: 14px; min-height: 56px; margin-bottom: 20px;}
  #v-cx #cx-hero .site-head .actions .talk{display: none;}
  #v-cx #cx-hero .site-head .mark, #v-cx #cx-hero .site-head .mark svg{width: 80px;}
  #v-cx #cx-hero .site-head .actions .login{padding: 12px; font-size: 11px;}
}

#v-cx #cx-hero .in{
  max-width: 1360px;
  margin-inline: auto;
  padding: 10px 12px 10px;
  text-align: left;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, .88fr);
  gap: clamp(30px, 4vw, 72px);
  align-items: center;
}
#v-cx #cx-hero .kick{
  display: inline-block;
  background: #ffffff;
  color: #3b66d6;
  border: 0;
  border-radius: 30px;
  padding: 6px 14px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .7px;
  text-transform: uppercase;
  margin-bottom: 20px;
}
#v-cx #cx-hero h1{
  font-size: clamp(35px, 4.2vw, 66px);
  line-height: 1.08;
  letter-spacing: -2px;
  font-weight: 400;
  color: #ffffff;
  margin: 0 0 24px;
  max-width: 14ch;
}
#v-cx #cx-hero .sub{
  font-size: 17px;
  line-height: 1.6;
  color: #edf2ff;
  max-width: 44ch;
  margin: 0 0 32px;
}
#v-cx #cx-hero .ctas{display:flex;gap:12px;justify-content:flex-start;align-items:center}
#v-cx #cx-hero .btn-glow{
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: #ffffff;
  color: #3b66d6;
  border-radius: 7px;
  padding: 14px 22px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .8px;
  text-transform: uppercase;
  cursor: pointer;
  text-decoration: none;
}
#v-cx #cx-hero .btn-glow::before{display:none}
#v-cx #cx-hero .btn-glow svg{width:14px;height:14px}
#v-cx #cx-hero .btn-line{
  display: inline-flex;
  align-items: center;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 7px;
  padding: 14px 22px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .8px;
  text-transform: uppercase;
  text-decoration: none;
}

/* ---- the device ---- */
#v-cx .phone{justify-self:center;width:min(392px,100%);
  border-radius:44px;padding:11px;background:#0B0D13;
  box-shadow:0 60px 120px rgba(6,10,26,.45), 0 0 0 1px rgba(244,241,232,.14) inset}
#v-cx .phone .scr{position:relative;background:#fff;border-radius:34px;overflow:hidden;
  font-family:var(--font);
  color:#101418}
#v-cx .phone .notch{position:absolute;left:50%;top:9px;transform:translateX(-50%);
  width:104px;height:24px;border-radius:14px;background:#0B0D13;z-index:2}
#v-cx .phone .top{display:flex;align-items:center;gap:9px;padding:34px 16px 13px;
  border-bottom:1px solid rgba(21,21,21,.08)}
#v-cx .phone .top .av{width:24px;height:24px;border-radius:7px;background:var(--deep);
  color:#fff;font-size:11px;display:grid;place-items:center;flex:0 0 auto}
#v-cx .phone .top b{font-weight:400;font-size:13px;color:#101418}
#v-cx .phone .top .live{margin-left:auto;display:inline-flex;align-items:center;gap:6px;
  font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--deep)}
#v-cx .phone .top .live i{width:6px;height:6px;border-radius:50%;background:var(--signal);
  font-style:normal;display:block}
#v-cx .phone .thread{padding:15px 16px 12px;display:flex;flex-direction:column;gap:13px}
#v-cx .phone .nm{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:#5F666D}
#v-cx .phone .b{max-width:88%;font-size:12.5px;line-height:1.5;border-radius:14px;padding:10px 13px}
#v-cx .phone .them .nm{margin-bottom:5px}
#v-cx .phone .them .b{background:#F2F1EC;color:#101418;border-bottom-left-radius:5px}
#v-cx .phone .me{align-self:flex-end;text-align:right;max-width:92%}
#v-cx .phone .me .nm{margin-bottom:5px}
#v-cx .phone .me .b{background:var(--signal);color:var(--paper);text-align:left;
  border-bottom-right-radius:5px;margin-left:auto}
#v-cx .phone .did{display:flex;align-items:center;gap:8px;margin:2px 0 0;
  font-size:11px;color:var(--deep);background:#EFF4FF;border:1px solid rgba(49,92,255,.22);
  border-radius:8px;padding:8px 11px}
#v-cx .phone .did svg{width:13px;height:13px;flex:0 0 auto}
#v-cx .phone .foot{display:flex;align-items:center;gap:8px;padding:11px 16px 15px;
  border-top:1px solid rgba(21,21,21,.08);font-size:11px;color:#5F666D}
#v-cx .phone .foot .dot{width:6px;height:6px;border-radius:50%;background:var(--deep);flex:0 0 auto}

@media(max-width:900px){
  #v-cx #cx-hero .in{grid-template-columns:1fr;text-align:center}
  #v-cx #cx-hero h1,#v-cx #cx-hero .sub{max-width:none;margin-inline:auto}
  #v-cx #cx-hero .ctas{justify-content:center}
  #v-cx .phone{margin-top:8px}
}

/* ===================== CX · ASK =====================
   The reference sets this block in blue on a flat pink field. White here, as
   asked. Signal Cobalt on white is 5.15:1, so the statement clears AA at any
   size; on Paper it would be 4.53 and marginal for body, which is why the
   field is genuinely white rather than the page's Paper. The edges fade
   through Paper so the joins above and below stay seamless. */
#v-cx #cx-ask{background:linear-gradient(180deg,
    #F4F1E8 0px,#FFFFFF 130px,#FFFFFF calc(100% - 130px),#F4F1E8 100%);
  padding:clamp(76px,8.5vw,132px) 0 clamp(86px,9.5vw,150px)}
#v-cx .askpill{display:inline-flex;align-items:center;gap:11px;flex-wrap:wrap;
  background:var(--pale);border-radius:8px;padding:13px 18px;
  margin-bottom:clamp(28px,3.4vw,48px)}
#v-cx .askpill svg{width:22px;height:22px;flex:0 0 auto}
#v-cx .askpill b{font-weight:400;font-size:var(--t-body);color:var(--deep)}
#v-cx .askpill span{font-size:var(--t-body);color:var(--graphite)}
#v-cx .askbody{font-size:clamp(25px,3.1vw,46px);line-height:1.3;letter-spacing:-.016em;
  font-weight:400;color:var(--signal);max-width:min(1180px,100%);text-wrap:pretty}
@media(max-width:700px){ #v-cx .askpill{align-items:flex-start;flex-direction:column;gap:6px} }

/* ===================== CX · SOLVE REAL PROBLEMS =====================
   The reference composition: outline chip, two-line statement, copy left and
   a checklist right, closing on two conversation cards -- one on the page
   ground showing the agent's reasoning, one on the cobalt field showing the
   answer and its sources.
   Colour notes: Signal on Paper is 4.53, fine for the display line but too
   close to the floor for body, so running copy is Deep Cobalt (8.57). On the
   cobalt card the customer bubbles are Paper rather than Pale -- Pale on
   Signal is 1.03 and the bubble would read as floating text with no shape. */
#v-cx #cx-solve{background:#F4F1E8;padding:clamp(84px,9vw,140px) 0 clamp(90px,10vw,150px)}
#v-cx .chip-o{display:inline-block;font-size:var(--t-small);color:var(--deep);
  border:1px solid rgba(49,92,255,.45);border-radius:6px;padding:7px 15px}
#v-cx #cx-solve h2{font-size:clamp(34px,4.8vw,74px);line-height:1.04;letter-spacing:-.026em;
  font-weight:400;color:var(--signal);margin:clamp(20px,2.4vw,32px) 0 0;max-width:16ch}
#v-cx .solverow{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);
  gap:clamp(28px,4vw,72px);align-items:start;margin-top:clamp(34px,4vw,58px)}
#v-cx .solverow p{font-size:var(--t-lead);line-height:1.6;color:var(--deep);max-width:50ch}
#v-cx .ticks{list-style:none;display:flex;flex-direction:column;gap:clamp(12px,1.4vw,18px);
  justify-self:end;padding-top:4px}
#v-cx .ticks li{display:flex;align-items:center;gap:13px;font-size:var(--t-lead);
  color:var(--deep);line-height:1.4}
#v-cx .ticks i{width:22px;height:22px;border-radius:5px;background:var(--pale);
  border:1px solid rgba(49,92,255,.5);display:grid;place-items:center;flex:0 0 auto}
#v-cx .ticks i svg{width:13px;height:13px;color:var(--deep)}

/* ---- the two conversation cards ---- */
#v-cx .convo{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));
  gap:clamp(14px,1.8vw,26px);margin-top:clamp(48px,5.4vw,86px)}
#v-cx .cv{border-radius:14px;padding:clamp(24px,3vw,44px) clamp(20px,2.6vw,38px);
  font-family:var(--font);
  display:flex;flex-direction:column;gap:14px;min-width:0}
#v-cx .cv-l{background:#fff;border:1px solid rgba(21,21,21,.09);
  box-shadow:0 22px 54px rgba(16,20,24,.09)}
#v-cx .cv-r{background:var(--signal);box-shadow:0 22px 54px rgba(24,56,168,.24)}
#v-cx .cv .who{display:flex;align-items:center;gap:9px;font-size:13px}
#v-cx .cv .who .mk{width:22px;height:22px;border-radius:6px;flex:0 0 auto;display:grid;
  place-items:center;font-size:10px}
#v-cx .cv-l .who{color:var(--deep)} #v-cx .cv-l .who .mk{background:var(--deep);color:#fff}
#v-cx .cv-r .who{color:var(--paper)} #v-cx .cv-r .who .mk{background:var(--paper);color:var(--deep)}
#v-cx .cv .bub{max-width:82%;font-size:13.5px;line-height:1.55;border-radius:12px;padding:12px 15px}
#v-cx .cv .right{align-self:flex-end}
/* left card: agent on Pale, customer on Signal */
#v-cx .cv-l .a{background:var(--pale);color:var(--deep)}
#v-cx .cv-l .c{background:var(--signal);color:var(--paper)}
/* right card: agent on white, customer on Paper -- both read as shapes on cobalt */
#v-cx .cv-r .a{background:#fff;color:#101418}
#v-cx .cv-r .c{background:var(--paper);color:#101418}

/* the reasoning trace, strung on a dashed line as in the reference */
#v-cx .trace{position:relative;margin:6px 0 6px 26px;padding-left:22px;
  display:flex;flex-direction:column;gap:9px}
#v-cx .trace::before{content:"";position:absolute;left:0;top:-8px;bottom:-8px;
  border-left:1px dashed rgba(49,92,255,.45)}
#v-cx .trace .lb{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--deep);
  margin-bottom:2px}
#v-cx .trace .lb b{font-weight:400}
#v-cx .trace .lb u{width:9px;height:9px;border-radius:50%;border:1px solid var(--signal);
  background:#fff;text-decoration:none;display:block;margin-left:-27px;flex:0 0 auto}
#v-cx .trace .r{display:flex;align-items:center;gap:10px;font-size:12.5px;color:#101418;
  border:1px solid rgba(49,92,255,.28);border-radius:8px;padding:10px 13px;background:#fff}
#v-cx .trace .r svg{width:14px;height:14px;color:var(--deep);flex:0 0 auto}
#v-cx .trace .r em{margin-left:auto;font-style:normal;color:var(--deep);font-size:12px}

/* sources */
#v-cx .srcs{margin-top:2px}
#v-cx .srcs .lb{font-size:12.5px;color:var(--paper);margin-bottom:9px}
#v-cx .srcs .row{display:flex;flex-wrap:wrap;gap:7px}
#v-cx .srcs .row span{display:inline-flex;align-items:center;gap:7px;font-size:12px;
  background:var(--paper);color:var(--deep);border-radius:7px;padding:7px 11px}
#v-cx .srcs .row svg{width:12px;height:12px;flex:0 0 auto}

@media(max-width:960px){
  #v-cx .solverow{grid-template-columns:1fr}
  #v-cx .ticks{justify-self:start}
  #v-cx .convo{grid-template-columns:1fr}
}

/* ---- thesis, on the same left-aligned template as the solve block ---- */
#v-cx #cx-thesis .head{max-width:none;text-align:left;margin:0}
#v-cx #cx-thesis h2{font-size:clamp(34px,4.8vw,74px);line-height:1.04;letter-spacing:-.026em;
  color:var(--signal);margin:clamp(20px,2.4vw,32px) 0 0;max-width:15ch;text-align:left}
#v-cx #cx-thesis .lede{color:var(--deep);text-align:left;margin:0;max-width:52ch}

/* ---- the question cards, rehoused at the foot of the page ---- */
#v-cx #cx-asks{background:#F4F1E8;padding:clamp(76px,8vw,124px) 0 clamp(84px,9vw,140px)}
#v-cx #cx-asks h2{font-size:clamp(34px,4.8vw,74px);line-height:1.04;letter-spacing:-.026em;
  color:var(--signal);margin:clamp(20px,2.4vw,32px) 0 0;max-width:15ch}

/* ===================== the flow, inside one panel =====================
   Reference: a single soft-ground shell holding the working surfaces, joined
   by a node on the centre line, with floating labels naming what each side
   is doing. */
#v-cx .shell{position:relative;margin-top:clamp(34px,4vw,56px);
  background:#F7F6F1;border:1px solid rgba(21,21,21,.07);border-radius:20px;
  padding:clamp(46px,5vw,78px) clamp(24px,3.4vw,58px) clamp(34px,4vw,60px)}
#v-cx .shell .rig{display:grid;grid-template-columns:minmax(0,.92fr) clamp(84px,9vw,150px) minmax(0,1.08fr);
  align-items:center;gap:0}
#v-cx .node{position:relative;display:grid;place-items:center;height:100%}
#v-cx .node .core{position:relative;z-index:2;width:70px;height:70px;border-radius:50%;
  background:var(--signal);display:grid;place-items:center;
  box-shadow:0 18px 40px rgba(24,56,168,.34)}
#v-cx .node .core svg{width:32px;height:32px;color:var(--paper)}
#v-cx .node .ring{position:absolute;border-radius:50%;border:1px dashed rgba(49,92,255,.35)}
#v-cx .node .r1{width:124px;height:124px}
#v-cx .node .r2{width:176px;height:176px;border-color:rgba(49,92,255,.18)}
#v-cx .node .halo{position:absolute;width:124px;height:124px;border-radius:50%;
  background:rgba(49,92,255,.07)}
/* the lines that tie each surface to the node */
#v-cx .node .wire{position:absolute;top:50%;height:1px;border-top:1px dashed rgba(49,92,255,.5)}
#v-cx .node .wl{left:-8%;width:52%} #v-cx .node .wr{right:-8%;width:52%}
#v-cx .node .pip{position:absolute;top:50%;width:7px;height:7px;border-radius:50%;
  background:var(--signal);transform:translateY(-50%)}
#v-cx .node .pl{left:6%} #v-cx .node .pr{right:6%}

#v-cx .flabel{position:absolute;display:inline-flex;align-items:center;gap:8px;
  background:#fff;border:1px solid rgba(21,21,21,.10);border-radius:999px;padding:8px 15px;
  font-size:var(--t-small);color:var(--deep);box-shadow:0 10px 26px rgba(16,20,24,.09);
  white-space:nowrap}
#v-cx .flabel i{width:7px;height:7px;border-radius:50%;background:var(--signal);
  font-style:normal;flex:0 0 auto}
#v-cx .fl-a{top:-18px;left:clamp(24px,4vw,64px)}
#v-cx .fl-b{top:-18px;right:clamp(24px,4vw,64px)}
#v-cx .fl-c{bottom:-18px;left:50%;transform:translateX(-50%)}

@media(max-width:960px){
  #v-cx .shell .rig{grid-template-columns:1fr;gap:20px}
  #v-cx .node{height:auto;padding:6px 0}
  #v-cx .node .wire,#v-cx .node .pip{display:none}
  #v-cx .flabel{position:static;transform:none;margin:0 6px 10px 0}
  #v-cx .fl-c{display:inline-flex}
}

/* ===================== the flow rig, second pass =====================
   Closer to the reference: a compact dialog on the left, two stacked cards on
   the right, and orthogonal wiring -- a dashed run in from the left, a solid
   spine down the right through the node. Labels sit on the element they name
   rather than on the shell edge. Copy is cut to the bone. */
#v-cx .shell{padding:clamp(52px,5.4vw,84px) clamp(24px,3.4vw,58px) clamp(52px,5.4vw,84px)}
#v-cx .rig2{display:grid;grid-template-columns:minmax(0,1fr) clamp(96px,11vw,190px) minmax(0,.82fr);
  align-items:center;gap:0}
#v-cx .rig2 .lab{display:inline-flex;align-self:flex-start;align-items:center;gap:8px;background:#fff;
  border:1px solid rgba(21,21,21,.10);border-radius:999px;padding:7px 14px;
  font-size:var(--t-small);color:var(--deep);box-shadow:0 8px 22px rgba(16,20,24,.08);
  white-space:nowrap;margin-bottom:14px}
#v-cx .rig2 .lab i{width:7px;height:7px;border-radius:50%;background:var(--signal);
  font-style:normal;flex:0 0 auto}
#v-cx .rig2 .lab.after{margin:14px 0 0}
#v-cx .col-l,#v-cx .col-r{display:flex;flex-direction:column;min-width:0;align-items:flex-start}
#v-cx .col-r{align-items:flex-start;gap:0}

/* the dialog */
#v-cx .dlg{width:100%;background:#fff;border:1px solid rgba(21,21,21,.09);border-radius:14px;
  box-shadow:0 24px 56px rgba(16,20,24,.10);padding:clamp(20px,2.2vw,28px);
  font-family:var(--font)}
#v-cx .dlg .fl{font-size:13px;color:#101418;margin-bottom:8px}
#v-cx .dlg .field{border:1px solid rgba(21,21,21,.14);border-radius:9px;padding:11px 13px;
  font-size:13px;color:#101418;margin-bottom:18px}
#v-cx .dlg .box{border:1px solid rgba(21,21,21,.14);border-radius:9px;padding:6px;margin-bottom:16px}
#v-cx .dlg .it{display:flex;align-items:center;gap:10px;padding:9px 9px;border-radius:7px;
  font-size:13px;color:#101418}
#v-cx .dlg .it + .it{border-top:1px solid rgba(21,21,21,.06)}
#v-cx .dlg .it.on{background:#F5F4F0}
#v-cx .dlg .tick{width:16px;height:16px;border-radius:4px;background:var(--signal);flex:0 0 auto;
  display:grid;place-items:center}
#v-cx .dlg .tick svg{width:10px;height:10px;color:#fff}
#v-cx .dlg .tick.off{background:#fff;border:1px solid rgba(21,21,21,.28)}
#v-cx .dlg .row{display:flex;align-items:center;gap:10px;font-size:13px;color:#101418;
  margin-bottom:18px}
#v-cx .dlg .acts{display:flex;justify-content:flex-end;gap:9px}
#v-cx .dlg .acts span{font-size:12.5px;border-radius:8px;padding:9px 15px}
#v-cx .dlg .acts .g{border:1px solid rgba(21,21,21,.16);color:#2A3038}
#v-cx .dlg .acts .s{background:var(--ink);color:var(--paper)}

/* the message card and the outcome menu */
#v-cx .msgc{background:#fff;border:1px solid rgba(21,21,21,.09);border-radius:14px;
  box-shadow:0 22px 52px rgba(16,20,24,.10);padding:16px 18px;width:100%;
  font-family:var(--font)}
#v-cx .msgc .hd{display:flex;align-items:center;gap:9px;margin-bottom:8px}
#v-cx .msgc .mk{width:26px;height:26px;border-radius:8px;background:var(--deep);color:#fff;
  display:grid;place-items:center;font-size:11px;flex:0 0 auto}
#v-cx .msgc b{font-weight:400;font-size:13.5px;color:#101418}
#v-cx .msgc em{font-style:normal;font-size:11.5px;color:#5F666D}
#v-cx .msgc p{font-size:13px;line-height:1.55;color:#2A3038}
#v-cx .menuc{background:#fff;border:1px solid rgba(21,21,21,.09);border-radius:14px;
  box-shadow:0 22px 52px rgba(16,20,24,.10);padding:7px;width:100%;
  font-family:var(--font)}
#v-cx .menuc .mi{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:9px;
  font-size:13px;color:#101418}
#v-cx .menuc .mi svg{width:15px;height:15px;color:#5F666D;flex:0 0 auto}
#v-cx .menuc .mi em{margin-left:auto;font-style:normal;font-size:11.5px;color:#5F666D}
#v-cx .menuc .mi.on{background:#F5F4F0}
#v-cx .menuc .mi.on svg{color:var(--deep)}

/* the wiring */
#v-cx .node2{position:relative;height:100%;display:grid;place-items:center}
#v-cx .node2 .spine{position:absolute;left:50%;top:14%;height:72%;width:1px;
  background:var(--signal);opacity:.55;transform:translateX(-50%)}
#v-cx .node2 .hwire{position:absolute;top:50%;left:-46%;width:96%;height:1px;
  border-top:1px dashed rgba(49,92,255,.55);transform:translateY(-50%)}
#v-cx .node2 .core{position:relative;z-index:2;width:66px;height:66px;border-radius:50%;
  background:var(--signal);display:grid;place-items:center;
  box-shadow:0 16px 36px rgba(24,56,168,.32)}
#v-cx .node2 .core svg{width:30px;height:30px;color:var(--paper)}
#v-cx .node2 .ring{position:absolute;border-radius:50%;border:1px dashed rgba(49,92,255,.30)}
#v-cx .node2 .r1{width:116px;height:116px;background:rgba(49,92,255,.07)}
#v-cx .node2 .r2{width:166px;height:166px;border-color:rgba(49,92,255,.16)}
#v-cx .node2 .pip{position:absolute;width:7px;height:7px;border-radius:2px;background:var(--signal)}
#v-cx .node2 .pt{left:50%;top:14%;transform:translate(-50%,-50%)}
#v-cx .node2 .pb{left:50%;bottom:14%;transform:translate(-50%,50%)}
#v-cx .node2 .pl{left:-46%;top:50%;transform:translateY(-50%);border-radius:50%}

@media(max-width:960px){
  #v-cx .rig2{grid-template-columns:1fr;gap:22px}
  #v-cx .node2{height:auto;padding:8px 0}
  #v-cx .node2 .spine,#v-cx .node2 .hwire,#v-cx .node2 .pip{display:none}
  #v-cx .col-r{gap:14px}
}

/* Landing composition matched to the supplied September reference. */
#v-home #stage{min-height:100svh;justify-content:flex-start}
#v-home #stage .hero{width:100%;text-align:center;align-items:center;
  justify-content:center;padding:clamp(120px,20svh,210px) var(--pad-x) clamp(110px,15svh,180px)}
#v-home #stage .hero h1{max-width:none;margin:0 auto 22px;
  font-size:var(--t-display);line-height:var(--lh-display);letter-spacing:-.02em;font-weight:400}
#v-home #stage .hero h1 em{color:inherit}
#v-home #stage .thesis{max-width:62ch;margin:0 auto 36px;text-align:center;color:rgba(244,241,232,.90)}
#v-home #stage .ctas{justify-content:center;align-items:stretch;gap:10px;margin-bottom:46px}
#v-home #stage .btn-solid,#v-home #stage .btn-ghost{padding:14px 28px;border-radius:2px;
  font-size:var(--t-label);letter-spacing:.08em;text-transform:uppercase;line-height:1.6}
#v-home #stage .btn-solid{background:var(--paper);color:var(--jet);border:1px solid var(--paper);font-weight:700}
#v-home #stage .btn-ghost{background:rgba(11,13,19,.55);color:var(--paper);
  border:1px solid rgba(244,241,232,.5);font-weight:400;backdrop-filter:blur(3px)}
#v-home #stage #herocard{width:100%;background:none;position:relative;z-index:2}
#v-home #stage #herocard .in{padding:0;margin:0}
#v-home #stage #herocard .card{width:min(100%,620px);margin:0 auto;padding:20px 22px;
  background:rgba(11,13,19,.88);border:1px solid rgba(244,241,232,.28);
  border-radius:6px;color:var(--paper);backdrop-filter:blur(6px);
  box-shadow:0 26px 60px rgba(0,0,0,.32)}
#v-home #stage #herocard .chip{background:transparent;border:1px solid rgba(244,241,232,.32);color:var(--paper)}
#v-home #stage #herocard .chip[aria-pressed="true"]{background:var(--paper);color:var(--jet);border-color:var(--paper)}
#v-home #stage #herocard .card .agent{color:rgba(244,241,232,.78);border:1px solid rgba(244,241,232,.28)}
#v-home #stage #herocard .card .agent i{color:rgba(244,241,232,.6)}
#v-home #stage #herocard .card .play{border:1px solid rgba(244,241,232,.5);color:var(--paper)}
#v-home #stage .btn:hover,#v-home #stage .chip:hover,#v-home #stage .play:hover{filter:brightness(1.12)}
@media(max-width:700px){
  #v-home #stage .hero{padding:80px var(--pad-x) 130px}
  #v-home #stage .hero h1{max-width:16ch}
  #v-home #stage .thesis{max-width:36ch}
  #v-home #stage .ctas{margin-bottom:32px}
  #v-home #stage #herocard .card{padding:18px}
  #v-home #stage #herocard .row{gap:9px}
  #v-home #stage #herocard .chip{padding:10px 12px}
  #v-home #stage #herocard .card .agent{margin-left:auto}
  #v-home #stage #herocard .spacer{flex-basis:100%;height:0}
}


/* Production feature grid: the reference's alternating 2:3 / 3:2 cards. */
#v-home #k0c.production-section{position:relative;isolation:isolate;display:block;height:auto;
  min-height:100svh;padding:clamp(120px,10vw,156px) var(--pad-x) clamp(108px,9vw,144px);
  color:var(--ink);background-color:#FAFAF8;overflow:hidden}
#v-home #k0c .production-inner{max-width:1160px;margin:0 auto}
#v-home #k0c .production-heading{text-align:center;max-width:1080px;margin:0 auto 52px}
#v-home #k0c .production-heading h2{max-width:none;margin:0 0 22px;font-weight:400;
  font-size:clamp(2.5rem,5.8vw,5rem);line-height:1.08;letter-spacing:-.03em;color:var(--ink);text-wrap:balance}
#v-home #k0c .production-heading p{max-width:52ch;margin:0 auto;font-size:clamp(1.375rem,2.7vw,2rem);
  line-height:1.4;color:#56606B;text-wrap:balance}
#v-home #k0c .production-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;align-items:start}
#v-home #k0c .production-card{position:relative;overflow:hidden;min-width:0;background:#fff;
  border:1px solid #CFD9ED;border-radius:0;color:#17213B}
/* Carry the opening hero's vertical colour field into each production illustration. */
#v-home #k0c .feature-stage{position:relative;isolation:isolate;display:flex;align-items:center;justify-content:center;
  width:100%;height:340px;padding:34px;overflow:hidden;background-color:#474b52;
  background-image:linear-gradient(180deg,transparent 72%,rgba(244,241,232,.24) 88%,rgba(244,241,232,.7) 100%),
    linear-gradient(rgba(11,13,19,.59),rgba(11,13,19,.59)),var(--hero-pattern);
  background-size:100% 100%;background-position:center;background-repeat:no-repeat}
#v-home #k0c .feature-window{display:block;width:100%;max-width:410px;background:#FDFCF9;border:1px solid #D5DADf;
  box-shadow:0 22px 40px -20px #0B0D1366;font-family:var(--font);font-weight:400}
#v-home #k0c .feature-window-bar{display:flex;align-items:center;gap:7px;min-height:46px;padding:12px 16px;
  border-bottom:1px solid #E1E4E7;color:#586777;font-size:.875rem;line-height:1.4}
#v-home #k0c .feature-window-bar i{display:block;width:5px;height:5px;border-radius:50%;background:#3b66d6;
  box-shadow:10px 0 #829F9B,20px 0 #AAA676;margin-right:22px;flex:none}
#v-home #k0c .feature-window-body{display:flex;align-items:center;justify-content:center;min-height:186px;padding:24px 20px}
#v-home #k0c .feature-diagram{display:block;width:100%;height:138px;overflow:visible}
#v-home #k0c .feature-diagram text{font-family:var(--font);font-size:14px;fill:#536576;letter-spacing:normal}
#v-home #k0c .feature-security{display:grid;grid-template-columns:86px minmax(0,1fr);align-items:center;gap:24px;width:100%}
#v-home #k0c .feature-lock{width:86px;height:86px;padding:22px;background:#EDF1F6;border:1px solid #CCD5DF;color:var(--signal)}
#v-home #k0c .feature-security-list{display:grid;gap:12px;font-size:.875rem;line-height:1.4;color:#53616F}
#v-home #k0c .feature-security-list>span{display:flex;gap:9px;align-items:center}
#v-home #k0c .feature-security-list svg{width:15px;height:15px;flex:none;color:#3b66d6}
/* Keep the existing native click and keyboard disclosure. */
#v-home #k0c .feature-disclosure summary{list-style:none;display:block;cursor:pointer;background:#fff}
#v-home #k0c .feature-disclosure summary::-webkit-details-marker{display:none}
#v-home #k0c .feature-disclosure summary::marker{content:''}
#v-home #k0c .feature-disclosure summary:focus-visible{outline:2px solid var(--signal);outline-offset:-4px}
#v-home #k0c .feature-front{display:flex;flex-direction:column;margin:0;font:inherit}
#v-home #k0c .feature-heading{display:flex;align-items:center;justify-content:space-between;min-height:122px;gap:20px;padding:28px}
#v-home #k0c .feature-title{font-size:clamp(1.5rem,2vw,2rem);font-weight:400;line-height:1.15;
  letter-spacing:-.025em;color:#17213B;max-width:22ch;margin:0;text-wrap:balance}
#v-home #k0c .feature-toggle{display:grid;place-items:center;width:36px;height:36px;flex:0 0 auto;
  border:1px solid #C6D2F1;color:var(--signal);transition:transform .2s,background .2s}
#v-home #k0c .feature-toggle svg{width:16px;height:16px}
#v-home #k0c .feature-disclosure summary:hover .feature-toggle{background:#EEF2FF}
#v-home #k0c .feature-disclosure[open] .feature-toggle{transform:rotate(45deg);background:#EEF2FF}
#v-home #k0c .feature-description{padding:0 28px 28px}
#v-home #k0c .feature-description p{max-width:none;font-size:1rem;line-height:1.55;color:#536078;
  margin:0;padding-top:20px;border-top:1px solid #E1E6F0}
#v-home #k0c .production-foot{display:flex;justify-content:center;align-items:center;
  flex-wrap:wrap;gap:14px 22px;margin-top:28px;color:#56606B;font-size:.9375rem;line-height:1.5}
#v-home #k0c .production-foot a{color:var(--ink);border-bottom:1px solid rgba(21,21,21,.3)}
@media(max-width:900px){
  #v-home #k0c .feature-stage{height:300px;padding:24px}
  #v-home #k0c .feature-heading{padding:24px;min-height:132px}
  #v-home #k0c .feature-description{padding:0 24px 24px}
  #v-home #k0c .feature-window-body{padding:22px 16px}
  #v-home #k0c .feature-security{grid-template-columns:64px minmax(0,1fr);gap:14px}
  #v-home #k0c .feature-lock{width:64px;height:64px;padding:16px}
}
@media(max-width:620px){
  #v-home #k0c.production-section{padding:112px var(--pad-x) 116px}
  #v-home #k0c .production-heading{margin-bottom:30px}
  #v-home #k0c .production-grid{grid-template-columns:1fr;gap:18px}
  #v-home #k0c .feature-stage{height:300px;padding:26px}
  #v-home #k0c .feature-heading{min-height:116px}
  #v-home #k0c .feature-title{font-size:1.75rem}
  #v-home #k0c .production-foot{text-align:center}
}

/* Soft blue-to-paper ground below the patterned opening hero. */
#v-home{isolation:isolate;min-height:100svh;background:#E8EDFF;color:var(--ink)}
#v-home::before{
  content:'';position:fixed;inset:0;z-index:-1;pointer-events:none;
  background:linear-gradient(180deg,#E8EDFF 0%,#E8EDFF 48%,#F4F1E8 100%)
}
#v-home #stack,
#v-home #k0c.production-section,
#v-home #k2c.developers-section,#v-home #connect,
#v-home #faq,#v-home #close,#v-home #foot{background:transparent!important}

#v-home #foot .ft-mark svg g[fill="#F4F1E8"]{fill:var(--ink)}
#v-home #connect .cn-tile{background:#fff}


/* One navy / logo-blue / paper blend across the Revenue Recovery scrolls.
   Paper at both section edges joins adjacent sections without a hard dark seam. */
#v-rr #rr-why,#v-rr #rr-sys,#v-rr #rr-conn,#v-rr #rr-deploy,#v-rr #rr-cta{
  background:linear-gradient(180deg,#F4F1E8 0px,#E8EDFF 24px,#0B153B 110px,#3b66d6 190px,
    #3b66d6 310px,#3b66d6 calc(100% - 160px),#E8EDFF calc(100% - 35px),#F4F1E8 100%);
  padding-top:240px;padding-bottom:200px;color:var(--paper)
}
#v-rr #rr-sys .ci{padding-top:0;padding-bottom:0}
#v-rr #rr-cta .in{padding-top:0;padding-bottom:0}
#v-rr #rr-why .stat,#v-rr #rr-why .stat b,
#v-rr #rr-sys .ci-copy h2,#v-rr #rr-sys .ci-copy .lede,
#v-rr #rr-conn .wrapc > h2.lede-run,#v-rr #rr-conn .wrapc > h2.lede-run b,
#v-rr #rr-deploy .wrapc > h2,#v-rr #rr-deploy .wrapc > .lede,
#v-rr #rr-deploy .close-line,#v-rr #rr-deploy .devshot figcaption,
#v-rr #rr-why .loop-note,#v-rr #rr-cta h2,#v-rr #rr-cta .lede{color:var(--paper)}
#v-rr #rr-deploy .close-line{border-left-color:#B8C7FF}
#v-rr #rr-cta .btn-solid{background:var(--paper);color:var(--jet)}
@media(max-width:640px){
 #v-rr #rr-why,#v-rr #rr-sys,#v-rr #rr-conn,#v-rr #rr-deploy,#v-rr #rr-cta{padding-top:220px;padding-bottom:180px}
}

/* Mobile presentation: same routes and content, adapted for touch and small screens. */
.mobile-menu-toggle{display:none}
.mobile-navigation{position:fixed;inset:16px 16px auto auto;margin:0;width:calc(100% - 32px);max-width:420px;max-height:calc(100dvh - 32px);overflow-y:auto;border:1px solid #D7E0F1;border-radius:12px;padding:22px;background:#F8FAFF;color:#17213B;box-shadow:0 24px 80px #07143155;font-family:var(--font)}
