#v-pricing .pricing-help{font-size:12px;line-height:1.65;color:#718099;margin:16px 0 0}
#v-pricing .pricing-model+ .pricing-model{border-top:1px solid #E7ECF4;padding-top:24px;margin-top:24px}
#v-pricing .pricing-model>label{display:flex;align-items:center;margin-bottom:14px;font-size:16px;gap:12px}
#v-pricing .pricing-symbol{display:grid;place-items:center;width:38px;height:38px;border-radius:8px;background:#EDF2FF;color:#3b66d6;font-size:19px;flex-shrink:0}
#v-pricing .pricing-model small{display:block;margin-top:3px;color:#7A879E;font-size:12px;font-weight:400}
#v-pricing .pricing-rate{font-size:12px;line-height:1.6;color:#6C7C98;margin:10px 0 0;overflow-wrap:anywhere}
#v-pricing .pricing-assumptions summary{display:flex;justify-content:space-between;cursor:pointer;font-size:15px;font-weight:500;min-height:24px}
#v-pricing .pricing-assumptions summary span{color:#3b66d6}
#v-pricing .pricing-assumptions[open] summary span{transform:rotate(45deg)}
#v-pricing .pricing-assumptions .pricing-fields{margin-top:22px}
#v-pricing .pricing-summary{position:sticky;top:24px;border:1px solid #CAD7F5;border-radius:12px;background:#fff;overflow:hidden;box-shadow:0 18px 60px -30px #29479B35}
#v-pricing .pricing-result{padding:30px}
#v-pricing .pricing-headline{display:grid;gap:8px}
#v-pricing .pricing-headline strong{font-size:clamp(38px,4vw,60px);letter-spacing:-.055em;font-weight:500;color:#3b66d6;overflow-wrap:anywhere}
#v-pricing .pricing-headline>span{color:#63708B;font-size:14px}
#v-pricing .pricing-month{border-top:1px solid #DFE6F4;margin-top:26px;padding-top:22px;display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:14px}
#v-pricing .pricing-month strong{font-weight:500;font-size:26px;letter-spacing:-.03em;overflow-wrap:anywhere}
#v-pricing .pricing-usage{font-size:12px;line-height:1.6;color:#718099;margin:12px 0 26px}
#v-pricing .pricing-breakdown{width:100%;border-collapse:collapse;table-layout:fixed;font-size:13px}
#v-pricing .pricing-breakdown th{font-weight:400;font-size:11px;color:#718099;padding:0 0 12px;text-align:right}
#v-pricing .pricing-breakdown th:first-child{width:43%;text-align:left}
#v-pricing .pricing-breakdown td{padding:14px 0;border-top:1px solid #E7ECF4;text-align:right;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
#v-pricing .pricing-breakdown td:first-child{text-align:left;padding-right:10px}
#v-pricing .pricing-breakdown small{display:block;font-size:10px;line-height:1.5;color:#8390A5;margin-top:3px}
#v-pricing .pricing-breakdown tr:last-child{font-weight:600;color:#3b66d6}
#v-pricing .pricing-summary-foot{background:#F2F5FF;padding:22px 30px;border-top:1px solid #DFE6F4}
#v-pricing .pricing-summary-foot p{font-size:12px;line-height:1.6;color:#63708B;margin:0 0 16px}
#v-pricing .pricing-summary-foot a{display:flex;justify-content:space-between;background:#3b66d6;color:white;padding:14px 18px;border-radius:5px;font-size:14px}
#v-pricing .pricing-error{color:#A23B44;font-size:13px;line-height:1.5;margin:15px 0}
#v-pricing .pricing-method{max-width:900px;margin:40px auto;color:#63708B;font-size:13px;line-height:1.7;border-top:1px solid #D6DEED;padding-top:22px}
