#v-pricing .pricing-method p{margin:12px 0}
#v-pricing .pricing-footer{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:32px 0;font-size:12px;color:#718099;border-top:1px solid #D6DEED}
