/* Pricing: illustrated introduction, paired plans and a stepped support grid. */
#v-pricing{background:linear-gradient(#F8FAFF,#FFFFFF 55%,#F4F1E8);color:#17213B}
#v-pricing .pricing-banner{margin:24px 28px 0;padding:32px 0 0;background:#3b66d6;border-radius:28px;overflow:hidden}
#v-pricing .pricing-banner .site-head{width:calc(100% - 112px);max-width:1160px;height:76px;border-radius:16px;background:#fff;margin:0 auto;--pad-x:24px}
#v-pricing .pricing-banner .site-head nav{gap:22px;font-size:14px}
#v-pricing .pricing-banner .actions{gap:14px;font-size:14px}
#v-pricing .pricing-hero{max-width:1160px;margin:auto;padding:78px 24px 82px;min-height:490px;display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);align-items:center;gap:24px}
#v-pricing .pricing-intro{text-align:left;padding:0;color:#fff}
#v-pricing .pricing-intro .pricing-kicker{display:inline-block;background:#fff;color:#3b66d6;padding:7px 13px;border-radius:30px;font-size:12px;margin-bottom:30px;letter-spacing:.035em}
#v-pricing .pricing-intro h1{font-size:clamp(48px,5.8vw,78px);line-height:1.02;color:#fff;letter-spacing:-.055em;font-weight:500}
#v-pricing .pricing-intro>p:not(.pricing-kicker){color:#EEF2FF;font-size:18px;margin:32px 0 0;max-width:330px}
#v-pricing .pricing-hero-art{width:100%;height:auto;display:block;max-height:430px;object-fit:contain}
#v-pricing .pricing-main{max-width:1160px;padding:0 24px}
#v-pricing .pricing-plan-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin:88px 0 42px}
#v-pricing .pricing-plan{background:#EBF1FF;border:1px solid #DCE6FF;border-radius:26px;overflow:hidden;display:flex;flex-direction:column;min-width:0}
#v-pricing .pricing-plan.business{background:#DFE7FF;border-color:#D5DFFF}
#v-pricing .pricing-plan-body{padding:0 32px 28px;position:relative;flex:1}
#v-pricing .pricing-plan-tag{display:table;padding:7px 12px;border-radius:0 0 7px 7px;background:#D6E2FF;color:#3b66d6;font-size:13px;font-weight:500;margin-bottom:28px}
#v-pricing .business .pricing-plan-tag{background:#C9D7FF}
#v-pricing .pricing-plan h2{font-size:36px;line-height:1.08;letter-spacing:-.045em;font-weight:400;margin:0 120px 20px 0;color:#3b66d6}
#v-pricing .pricing-plan p{font-size:16px;line-height:1.55;color:#506594;margin:0;max-width:360px}
#v-pricing .pricing-plan .pricing-plan-features{margin-top:22px;font-size:14px;line-height:1.9}
#v-pricing .pricing-plan-footer{padding:24px 32px;background:#FFFFFF30}
#v-pricing .pricing-toggle,#v-pricing .pricing-plan-footer>a{display:inline-flex;align-items:center;justify-content:center;gap:20px;max-width:100%;min-height:48px;padding:13px 20px;border:0;border-radius:9px;background:#3b66d6;color:#fff;font:15px var(--font);line-height:1.4;cursor:pointer;text-decoration:none}
#v-pricing .pricing-toggle:hover,#v-pricing .pricing-plan-footer>a:hover{background:#3b66d6}
#v-pricing .pricing-toggle:focus-visible{outline:2px solid #3b66d6;outline-offset:4px}
#v-pricing .pricing-toggle>span{font-size:22px;line-height:1}
#v-pricing .pricing-toggle[aria-expanded=true]>span{transform:rotate(45deg)}
#v-pricing .pricing-calculator{margin:0 0 48px;padding-top:12px;scroll-margin-top:24px}
#v-pricing .pricing-calculator-heading{font-size:32px;font-weight:400;letter-spacing:-.04em;margin-bottom:24px}
#v-pricing .pricing-spot{display:block;width:104px;height:104px;mix-blend-mode:multiply;background-image:url('data:image/png;base64,');background-repeat:no-repeat;background-size:300% 400%;background-position:var(--spot-x,0%) var(--spot-y,0%)}
#v-pricing .pricing-plan .pricing-spot{position:absolute;right:20px;top:46px}









#v-pricing .pricing-support{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin-bottom:100px}
#v-pricing .pricing-support-intro{grid-column:1 / -1;grid-row:auto;align-self:center;max-width:550px;padding:8px 0}
