#v-pricing .pricing-support-intro h2 strong{font-weight:600}
#v-pricing .pricing-support-intro p{font-size:16px;line-height:1.6;color:#63708B;max-width:350px}
#v-pricing .pricing-resource{background:#EFF3FF;border:1px solid #E7EDFB;border-radius:22px;padding:22px;min-height:245px;position:relative}
#v-pricing .pricing-resource:nth-of-type(3n){background:#E6EDFF}
