#v-pricing .pricing-resource h3{font-size:19px;font-weight:500;letter-spacing:-.025em;margin:0 0 10px}
#v-pricing .pricing-resource p{font-size:14px;line-height:1.55;color:#63708B;margin:0}
#v-pricing .pricing-resource a{display:inline-block;font-size:14px;color:#3b66d6;margin-top:14px;text-decoration:underline;text-underline-offset:3px}
#v-pricing .pricing-resource-status{position:absolute;top:24px;right:20px;font-size:11px;color:#7182A4}
